/* 应用时间统一看板 —— Cloudflare Worker + D1 单文件版
 * 前端 HTML 由 build.py 内联注入到下方 HTML 常量。
 * 时区统一按北京时间 GMT+8 处理。
 */

const HTML = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, viewport-fit=cover\">\n<title>应用时间统一看板</title>\n<meta name=\"description\" content=\"vivo X90 与 iPad Air 6 的使用时长、打开次数与时间线\">\n<meta name=\"theme-color\" content=\"#0f172a\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\">\n<meta name=\"apple-mobile-web-app-title\" content=\"时间看板\">\n<link rel=\"manifest\" href=\"/manifest.webmanifest\">\n<link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n<link rel=\"icon\" href=\"/icon-192.png\" type=\"image/png\">\n<style>\n/* ============================================================\n   应用时间看板 · 视觉样式\n   ============================================================ */\n:root{\n  color-scheme:light dark;\n  --bg:#f5f6fb;\n  --card:#ffffff;\n  --card-2:#f8fafd;\n  --text:#0f172a;\n  --text-2:#475569;\n  --muted:#7b879a;\n  --line:#e9edf4;\n  --line-strong:#dae1ec;\n  --primary:#4f46e5;\n  --primary-2:#6366f1;\n  --primary-d:#4338ca;\n  --primary-soft:#eef0ff;\n  --vivo:#10b981;\n  --vivo-2:#059669;\n  --ipad:#f59e0b;\n  --ipad-2:#f97316;\n  --danger:#ef4444;\n  --radius:14px;\n  --radius-sm:10px;\n  --shadow-sm:0 1px 2px rgba(16,24,40,.04),0 1px 3px rgba(16,24,40,.04);\n  --shadow-md:0 2px 4px rgba(16,24,40,.04),0 14px 30px -14px rgba(16,24,40,.16);\n  --shadow-primary:0 8px 18px -8px rgba(79,70,229,.55);\n  --heat0:#eef1fb;--heat1:#c8cef7;--heat2:#8587ee;--heat3:#4f46e5;\n}\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%}\nbody{\n  margin:0;color:var(--text);font-size:14px;line-height:1.5;\n  font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",\"PingFang SC\",\"Hiragino Sans GB\",\"Microsoft YaHei\",sans-serif;\n  -webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;\n  overflow-x:clip;\n  background:\n    radial-gradient(1100px 520px at 8% -8%,#e8ecff 0%,rgba(232,236,255,0) 62%),\n    radial-gradient(900px 460px at 102% -4%,#fdeef7 0%,rgba(253,238,247,0) 58%),\n    var(--bg);\n  background-attachment:fixed;\n  min-height:100vh;\n}\n::-webkit-scrollbar{width:10px;height:10px}\n::-webkit-scrollbar-thumb{background:rgba(123,135,154,.32);border-radius:99px;border:2px solid transparent;background-clip:content-box}\n::-webkit-scrollbar-thumb:hover{background:rgba(123,135,154,.5);background-clip:content-box}\n:focus-visible{outline:2px solid var(--primary-2);outline-offset:2px}\n\n/* ---------- 顶栏 ---------- */\n.topbar{\n  position:sticky;top:0;z-index:50;\n  display:flex;align-items:center;justify-content:space-between;gap:18px;\n  height:66px;padding:0 26px;\n  background:rgba(255,255,255,.76);\n  -webkit-backdrop-filter:saturate(180%) blur(16px);\n  backdrop-filter:saturate(180%) blur(16px);\n  border-bottom:1px solid rgba(233,237,244,.9);\n}\n.brand{display:flex;align-items:center;gap:11px;font-size:16px;font-weight:700;letter-spacing:-.01em;white-space:nowrap}\n.logo{\n  width:34px;height:34px;border-radius:11px;flex:none;\n  display:grid;place-items:center;color:#fff;\n  background:linear-gradient(140deg,#818cf8,#4338ca);\n  box-shadow:var(--shadow-primary);\n}\n.logo svg{width:19px;height:19px;display:block}\n.brand small{color:var(--muted);font-size:11.5px;font-weight:500;margin-left:2px;letter-spacing:0}\n.tabs{\n  display:flex;gap:3px;padding:4px;border-radius:12px;\n  background:rgba(241,244,250,.85);border:1px solid rgba(233,237,244,.9);\n}\n.tab{\n  border:0;background:transparent;color:var(--text-2);\n  font-size:13.5px;font-weight:500;padding:0 15px;height:32px;\n  border-radius:9px;cursor:pointer;white-space:nowrap;\n  transition:background .2s,color .2s,box-shadow .2s;\n}\n.tab:hover{background:rgba(255,255,255,.78);color:var(--text)}\n.tab.active{\n  background:linear-gradient(140deg,var(--primary-2),var(--primary-d));\n  color:#fff;font-weight:600;box-shadow:var(--shadow-primary);\n}\n\nmain{max-width:1200px;margin:26px auto 60px;padding:0 22px;min-width:0}\n.page{display:none}\n@keyframes fadeUp{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}\n.page.active{display:block;animation:fadeUp .38s cubic-bezier(.22,1,.36,1)}\n\n/* ---------- 卡片 ---------- */\n.card{\n  background:var(--card);border:1px solid var(--line);border-radius:var(--radius);\n  padding:20px 22px;margin-bottom:18px;box-shadow:var(--shadow-sm);\n  transition:box-shadow .28s ease;\n  max-width:100%;min-width:0;overflow-wrap:anywhere;\n}\n.card:hover{box-shadow:var(--shadow-md)}\n.card.narrow{max-width:860px}\n.card h2{\n  display:flex;align-items:center;gap:9px;margin:0 0 16px;\n  font-size:15px;font-weight:650;letter-spacing:-.01em;color:var(--text);\n}\n.card h2::before{\n  content:\"\";width:3px;height:15px;border-radius:3px;flex:none;\n  background:linear-gradient(180deg,var(--primary-2),var(--primary-d));\n}\n.hint{font-size:11.5px;color:var(--muted);font-weight:400;margin-left:auto;letter-spacing:0}\n\n/* ---------- 筛选条 ---------- */\n.filters{display:flex;align-items:flex-end;gap:14px;flex-wrap:wrap;padding:16px 20px}\n.filter-item{display:flex;flex-direction:column;gap:6px}\n.filter-item label{font-size:11.5px;font-weight:600;color:var(--muted);letter-spacing:.02em}\n.sync-note{\n  margin-left:auto;align-self:center;display:inline-flex;align-items:center;gap:6px;\n  font-size:11.5px;color:var(--muted);white-space:nowrap;\n  padding:5px 11px;border-radius:999px;background:var(--bg);border:1px solid var(--line);\n}\n.sync-note .dot{width:7px;height:7px}\n.sync-note .sync-sep{opacity:.45;margin:0 1px}\n\n/* ---------- 表单控件 ---------- */\ninput,select,button{font-family:inherit;font-size:13.5px;color:var(--text)}\ninput,select{\n  background:var(--card);border:1px solid var(--line-strong);border-radius:var(--radius-sm);\n  padding:8px 11px;min-height:38px;\n  transition:border-color .2s,box-shadow .2s;\n}\ninput:focus,select:focus{outline:0;border-color:var(--primary-2);box-shadow:0 0 0 4px rgba(99,102,241,.14)}\nbutton{\n  border:1px solid var(--line-strong);background:var(--card);border-radius:var(--radius-sm);\n  padding:8px 16px;min-height:38px;cursor:pointer;font-weight:500;\n  transition:transform .18s,box-shadow .2s,background .2s,border-color .2s;\n}\nbutton:hover{background:var(--card-2);border-color:#c9d3e2}\nbutton:active{transform:translateY(1px)}\nbutton.primary{\n  background:linear-gradient(140deg,var(--primary-2),var(--primary-d));\n  border-color:transparent;color:#fff;font-weight:600;box-shadow:var(--shadow-primary);\n}\nbutton.primary:hover{filter:brightness(1.07);box-shadow:0 10px 22px -8px rgba(79,70,229,.62)}\nbutton.danger{\n  background:linear-gradient(140deg,#f87171,#dc2626);\n  border-color:transparent;color:#fff;font-weight:600;box-shadow:0 8px 18px -8px rgba(239,68,68,.55);\n}\nbutton.danger:hover{filter:brightness(1.06)}\n\n/* ---------- KPI ---------- */\n.kpi-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:18px}\n.kpi{position:relative;overflow:hidden;padding:18px 20px;margin:0}\n.kpi::after{\n  content:\"\";position:absolute;right:-40px;top:-44px;width:112px;height:112px;border-radius:50%;\n  background:radial-gradient(circle,rgba(99,102,241,.1),transparent 70%);pointer-events:none;\n}\n.kpi-top{display:flex;align-items:center;gap:10px;margin-bottom:13px;position:relative}\n.kpi-icon{width:30px;height:30px;border-radius:9px;display:grid;place-items:center;flex:none;background:var(--primary-soft);color:var(--primary)}\n.kpi-icon svg{width:16px;height:16px;display:block}\n.kpi-label{font-size:12.5px;font-weight:500;color:var(--muted)}\n.kpi-value{\n  position:relative;font-size:26px;font-weight:750;letter-spacing:-.02em;line-height:1.1;\n  color:var(--text);font-variant-numeric:tabular-nums;\n}\n.kpi-time .kpi-icon{background:#eef0ff;color:#4f46e5}\n.kpi-count .kpi-icon{background:#e6f7f1;color:#0d9488}\n.kpi-apps .kpi-icon{background:#f4ecff;color:#8b5cf6}\n.kpi-ipad .kpi-icon{background:#fff2e2;color:#f59e0b}\n\n.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:18px}\n\n/* ---------- 趋势柱状图 ---------- */\n.chart-trend{\n  display:flex;align-items:flex-end;gap:6px;height:210px;\n  padding:14px 2px 0;border-bottom:1px solid var(--line);\n  overflow:visible;\n}\n/* 提示框只在悬停时出现，用 visibility 隐藏而非 display:none，\n   避免它在隐藏状态下仍参与宽度计算、把页面撑出横向滚动条 */\n.chart-trend .trend-tip{visibility:hidden}\n.chart-trend .trend-col:hover .trend-tip{visibility:visible}\n.trend-col{\n  flex:1;min-width:0;height:100%;display:flex;flex-direction:column;\n  align-items:center;justify-content:flex-end;gap:7px;position:relative;\n}\n.trend-stack{\n  width:100%;max-width:48px;display:flex;flex-direction:column-reverse;overflow:hidden;\n  border-radius:7px 7px 3px 3px;min-height:3px;\n  box-shadow:0 8px 16px -10px rgba(16,24,40,.55);\n  transition:filter .2s,transform .2s;\n}\n.trend-col:hover .trend-stack{filter:brightness(1.08);transform:translateY(-2px)}\n.trend-seg.vivo{background:linear-gradient(180deg,#34d399,#059669)}\n.trend-seg.ipad{background:linear-gradient(180deg,#fbbf24,#f97316)}\n.trend-label{font-size:10px;color:var(--muted);white-space:nowrap;font-variant-numeric:tabular-nums}\n.trend-tip{\n  position:absolute;bottom:100%;left:50%;z-index:5;transform:translate(-50%,-6px);\n  background:#0f172a;color:#fff;font-size:11px;font-weight:500;\n  padding:6px 9px;border-radius:8px;white-space:nowrap;pointer-events:none;\n  opacity:0;transition:opacity .18s,transform .18s;box-shadow:0 10px 24px -8px rgba(0,0,0,.45);\n}\n.trend-col:hover .trend-tip{opacity:1;transform:translate(-50%,-10px)}\n.chart-trend > .hint{align-self:flex-end;padding-bottom:2px}\n/* 首尾列的提示框贴边对齐，避免超出视口产生横向滚动 */\n#chart-trend .trend-col:first-child .trend-tip{left:0;transform:translate(0,-6px)}\n#chart-trend .trend-col:first-child:hover .trend-tip{transform:translate(0,-10px)}\n#chart-trend .trend-col:last-child .trend-tip{left:auto;right:0;transform:translate(0,-6px)}\n#chart-trend .trend-col:last-child:hover .trend-tip{transform:translate(0,-10px)}\n\n/* ---------- App 排行 ---------- */\n.chart-apps{display:flex;flex-direction:column;gap:11px}\n.app-row{display:flex;align-items:center;gap:12px}\n.app-name{\n  width:104px;flex:none;font-size:12.5px;font-weight:500;color:var(--text-2);\n  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;\n}\n.app-bar-wrap{\n  flex:1;min-width:0;height:20px;background:#f1f4fa;border-radius:8px;\n  position:relative;overflow:hidden;box-shadow:inset 0 1px 2px rgba(16,24,40,.05);\n}\n.app-bar{\n  height:100%;border-radius:8px;box-shadow:0 2px 6px -2px rgba(16,24,40,.28);\n  transition:width .7s cubic-bezier(.22,1,.36,1);\n}\n.app-bar.vivo{background:linear-gradient(90deg,#34d399,#059669)}\n.app-bar.ipad{background:linear-gradient(90deg,#fbbf24,#f97316)}\n.app-bar.both{background:linear-gradient(90deg,#818cf8,#4f46e5)}\n.tag.both{background:rgba(99,102,241,.15);color:#4338ca;margin-left:6px;font-size:10px}\n.app-time{\n  width:66px;flex:none;text-align:right;font-size:12px;font-weight:600;\n  color:var(--text-2);font-variant-numeric:tabular-nums;\n}\n\n/* ---------- 热力图 ---------- */\n.heatmap{display:grid;grid-template-columns:repeat(24,1fr);gap:5px}\n.heat-cell{\n  aspect-ratio:1;min-width:0;border-radius:8px;display:flex;align-items:center;justify-content:center;\n  font-size:9px;font-weight:600;color:var(--muted);font-variant-numeric:tabular-nums;\n  transition:transform .18s,box-shadow .18s;\n}\n.heat-cell:hover{transform:scale(1.22);position:relative;z-index:3;box-shadow:0 6px 14px -6px rgba(16,24,40,.45)}\n.heat-cell.h0{background:var(--heat0)}\n.heat-cell.h1{background:var(--heat1);color:#4c51a8}\n.heat-cell.h2{background:var(--heat2);color:#fff}\n.heat-cell.h3{background:var(--heat3);color:#fff;box-shadow:0 4px 12px -6px rgba(79,70,229,.85)}\n.legend{display:flex;align-items:center;gap:9px;justify-content:flex-end;margin-top:12px;font-size:11px;color:var(--muted)}\n.legend-bar{width:132px;height:9px;border-radius:99px;background:linear-gradient(90deg,var(--heat0),var(--heat1),var(--heat2),var(--heat3))}\n\n/* ---------- 时间线 ---------- */\n.timeline-legend{display:flex;flex-wrap:wrap;gap:16px;margin-bottom:24px;font-size:12px;color:var(--muted)}\n.timeline-legend span{display:inline-flex;align-items:center;gap:6px}\n.dot{width:9px;height:9px;border-radius:50%;display:inline-block;flex:none}\n.dot.vivo{background:var(--vivo);box-shadow:0 0 0 3px rgba(16,185,129,.16)}\n.dot.ipad{background:var(--ipad);box-shadow:0 0 0 3px rgba(245,158,11,.16)}\n.timeline{position:relative}\n.tl-lane{position:relative;height:66px;border-bottom:1px dashed var(--line);margin-bottom:10px}\n.tl-lane-label{position:absolute;left:0;top:-17px;font-size:11px;font-weight:600;color:var(--muted);letter-spacing:.02em}\n.tl-track{position:absolute;left:0;right:0;top:16px;bottom:6px}\n.tl-block{\n  position:absolute;top:0;height:100%;min-width:3px;border-radius:6px;\n  font-size:10px;font-weight:600;color:#fff;padding:3px 5px;overflow:hidden;white-space:nowrap;\n  transition:filter .18s,transform .18s,box-shadow .18s;\n}\n.tl-block.vivo{background:linear-gradient(180deg,#34d399,#059669)}\n.tl-block.ipad{background:linear-gradient(180deg,#fbbf24,#f97316)}\n.tl-block:hover{filter:brightness(1.1);transform:translateY(-1px);z-index:2;box-shadow:0 8px 18px -8px rgba(16,24,40,.55)}\n.tl-block.estimated{border:2px dashed rgba(255,255,255,.9);box-sizing:border-box}\n.tl-axis{\n  position:absolute;left:0;right:0;bottom:0;display:flex;justify-content:space-between;\n  font-size:10px;color:var(--muted);font-variant-numeric:tabular-nums;\n}\n.tl-empty{\n  position:absolute;left:2px;top:50%;transform:translateY(-50%);\n  font-size:11px;color:var(--muted);white-space:nowrap;\n}\n\n/* ---------- 表格 ---------- */\n.table-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:12px;max-width:100%;min-width:0}\ntable{width:100%;border-collapse:collapse;font-size:12.5px}\nth,td{text-align:left;padding:11px 14px;white-space:nowrap;border-bottom:1px solid var(--line)}\nthead th{background:var(--card-2);color:var(--muted);font-weight:600;font-size:11.5px;letter-spacing:.03em}\ntbody tr{transition:background .15s}\ntbody tr:hover{background:rgba(99,102,241,.045)}\ntbody tr:last-child td{border-bottom:0}\ntd:nth-child(3),td:nth-child(4),td:nth-child(5){font-variant-numeric:tabular-nums}\n.tag{display:inline-block;padding:3px 9px;border-radius:99px;font-size:10.5px;font-weight:600;line-height:1.5}\n.tag.vivo{background:#e6f7f1;color:#047857}\n.tag.ipad{background:#fff4e5;color:#b45309}\n.tag.est{background:#fee2e2;color:#b91c1c;margin-left:6px}\n.empty{text-align:center;color:var(--muted);padding:34px 12px;font-size:12.5px}\n\n/* ---------- 文字与说明 ---------- */\n.desc{color:var(--muted);line-height:1.85;font-size:13px}\nh3.sub{\n  margin:22px 0 10px;font-size:13.5px;font-weight:700;color:var(--text);\n  display:flex;align-items:center;gap:8px;letter-spacing:.01em;\n}\nh3.sub::before{content:\"\";width:3px;height:13px;border-radius:2px;background:linear-gradient(180deg,var(--primary-2),var(--primary))}\n.desc strong,.steps strong{color:var(--text);font-weight:600}\n.muted-text{color:var(--muted)}\n.result{margin-top:12px;font-size:12.5px;font-weight:500;color:var(--primary-d)}\n.inline-form{display:flex;gap:9px;max-width:440px;flex-wrap:wrap}\nform{display:flex;gap:9px;align-items:center;flex-wrap:wrap}\n.steps{line-height:1.95;padding-left:22px;color:var(--text-2);font-size:13px}\n.steps li{margin-bottom:8px;padding-left:2px}\n.steps li::marker{color:var(--primary);font-weight:700}\ncode{\n  background:rgba(79,70,229,.08);color:#4338ca;padding:2px 6px;border-radius:6px;\n  font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:12px;font-weight:500;\n}\ncode.block{\n  display:block;padding:12px 14px;margin-top:8px;white-space:pre-wrap;word-break:break-all;\n  background:var(--card-2);border:1px solid var(--line);color:var(--primary-d);border-radius:10px;\n}\na{color:var(--primary-d);text-decoration:none;border-bottom:1px solid rgba(79,70,229,.3);transition:border-color .2s}\na:hover{border-bottom-color:var(--primary)}\n.warn{\n  background:rgba(245,158,11,.09);border:1px solid rgba(245,158,11,.22);border-left:4px solid var(--ipad);\n  border-radius:10px;padding:12px 15px;margin:14px 0;line-height:1.85;color:#92400e;font-size:12.5px;\n}\n.info-card{\n  background:rgba(79,70,229,.07);border:1px solid rgba(79,70,229,.16);border-left:4px solid var(--primary-2);\n  border-radius:10px;padding:12px 15px;margin-bottom:16px;line-height:1.8;color:#3730a3;font-size:12.5px;\n}\n.danger-zone{border-color:rgba(239,68,68,.28);background:linear-gradient(180deg,rgba(239,68,68,.03),transparent)}\n\n/* ---------- 数据新鲜度横幅 ---------- */\n.fresh-banner{\n  display:flex;align-items:center;gap:9px;\n  max-width:1180px;margin:12px auto 0;padding:10px 16px;\n  border-radius:12px;font-size:12.5px;line-height:1.6;\n}\n.fresh-banner[hidden]{display:none}\n.fresh-banner.warn{background:rgba(239,68,68,.08);border:1px solid rgba(239,68,68,.24);color:#b91c1c}\n.fresh-banner .fb-icon{font-size:15px;flex:none}\n\n/* ---------- KPI 口径提示 ---------- */\n.kpi-hint{\n  margin:-4px 0 18px;padding:0 4px;font-size:12px;line-height:1.7;color:var(--primary-d);\n}\n.kpi-hint.muted{color:var(--muted)}\n\n/* ---------- 节假日标记 ---------- */\n.trend-label{display:flex;flex-direction:column;align-items:center;gap:3px}\n.day-mark{width:6px;height:6px;border-radius:50%;display:block;background:var(--muted);opacity:.55}\n.day-mark.work{background:var(--vivo);opacity:.75}\n.day-mark.rest{background:var(--ipad);opacity:.75}\n.day-mark.holiday{background:var(--danger);opacity:.9}\n.day-mark.makeup{background:var(--primary-2);opacity:.9}\n.day-legend{display:flex;gap:14px;flex-wrap:wrap;margin-top:12px;font-size:11.5px;color:var(--muted)}\n.day-legend .dot{width:7px;height:7px;box-shadow:none;margin-right:4px}\n.dot.day-work{background:var(--vivo)}\n.dot.day-rest{background:var(--ipad)}\n.dot.day-holiday{background:var(--danger)}\n.dot.day-makeup{background:var(--primary-2)}\n\n/* ---------- 时间轴筛选 ---------- */\n.tl-tools{display:flex;align-items:center;gap:10px;margin-bottom:12px;flex-wrap:wrap}\n.tl-tools input[type=search]{\n  flex:0 1 220px;padding:7px 12px;border-radius:9px;\n  border:1px solid var(--line-strong);background:var(--card-2);color:var(--text);font-size:12.5px;\n}\n.tl-tools input[type=search]:focus{outline:2px solid rgba(79,70,229,.35);outline-offset:1px}\n\n/* ---------- 卡片操作按钮 ---------- */\n.card-actions{display:flex;gap:8px;margin-bottom:10px;flex-wrap:wrap}\nbutton.ghost{\n  background:transparent;border:1px solid var(--line-strong);color:var(--text-2);\n  padding:6px 12px;border-radius:9px;font-size:12px;font-weight:500;cursor:pointer;transition:all .18s;\n}\nbutton.ghost:hover{border-color:var(--primary);color:var(--primary-d);background:var(--primary-soft)}\n.inline-label{font-size:12.5px;color:var(--text-2);align-self:center}\n.inline-form input[type=text],.inline-form input[type=number]{\n  padding:7px 11px;border-radius:9px;border:1px solid var(--line-strong);\n  background:var(--card-2);color:var(--text);font-size:12.5px;min-width:0;\n}\n.inline-form input[type=number]{width:96px}\n.inline-form input[type=text]{flex:1 1 190px}\n\n/* ---------- 数据管理页 ---------- */\n.manage-status{font-size:13px;color:var(--text-2);line-height:1.8}\n.manage-status table{width:100%;margin-bottom:6px}\n.manage-status .desc{font-size:12.5px;margin:0}\npre.pre{\n  margin:8px 0 0;padding:10px 12px;border-radius:9px;\n  background:var(--card-2);border:1px solid var(--line);\n  font-size:12px;line-height:1.7;white-space:pre-wrap;word-break:break-word;\n  font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;color:var(--text-2);\n}\n\n\n/* ---------- 分析页 ---------- */\n.report{line-height:1.95;font-size:13px;color:var(--text-2)}\n.report .hl{color:var(--primary-d);font-weight:700;font-variant-numeric:tabular-nums}\n.report .sec{margin-bottom:12px}\n.report ul{margin:6px 0;padding-left:20px}\n.report li{margin-bottom:3px}\n.goals{display:flex;flex-direction:column;gap:14px}\n.goal-row{display:flex;align-items:center;gap:12px}\n.goal-name{width:86px;flex:none;font-size:12.5px;font-weight:600;color:var(--text-2)}\n.goal-track{\n  flex:1;min-width:0;height:24px;background:#f1f4fa;border-radius:99px;position:relative;\n  box-shadow:inset 0 1px 2px rgba(16,24,40,.05);\n}\n.goal-fill{height:100%;border-radius:99px;transition:width .7s cubic-bezier(.22,1,.36,1)}\n.goal-fill.ok{background:linear-gradient(90deg,#34d399,#059669)}\n.goal-fill.over{background:linear-gradient(90deg,#fb7185,#dc2626)}\n.goal-fill.none{background:linear-gradient(90deg,#fbbf24,#f97316)}\n.goal-text{\n  position:absolute;right:8px;top:50%;transform:translateY(-50%);\n  font-size:10.5px;font-weight:700;color:#0f172a;font-variant-numeric:tabular-nums;\n  background:rgba(255,255,255,.9);padding:2px 8px;border-radius:99px;\n  box-shadow:0 1px 3px rgba(16,24,40,.14);white-space:nowrap;\n}\n.goal-input{width:64px;text-align:center;padding:4px 6px;min-height:30px}\n.goal-unit{font-size:12px;color:var(--muted);flex:none}\n.rules-editor{\n  width:100%;height:180px;resize:vertical;padding:12px;\n  font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:12px;line-height:1.7;\n  background:var(--card);color:var(--text);border:1px solid var(--line-strong);border-radius:12px;\n  transition:border-color .2s,box-shadow .2s;\n}\n.rules-editor:focus{outline:0;border-color:var(--primary-2);box-shadow:0 0 0 4px rgba(99,102,241,.14)}\n\n/* 周对比：仅两组，居中收窄，说明文字右上角 */\n#chart-compare{position:relative;justify-content:center;gap:72px}\n#chart-compare .trend-col{max-width:170px}\n#chart-compare > .hint{position:absolute;right:4px;top:2px;margin:0;align-self:auto;padding:0}\n\n/* ---------- 响应式 ---------- */\n@media(max-width:1000px){\n  .kpi-grid{grid-template-columns:repeat(2,1fr)}\n  .grid-2{grid-template-columns:1fr}\n}\n@media(max-width:760px){\n  .heatmap{grid-template-columns:repeat(12,1fr)}\n}\n@media(max-width:640px){\n  .topbar{height:auto;flex-wrap:wrap;padding:10px 14px;gap:10px}\n  .brand small{display:none}\n  .tabs{width:100%;overflow-x:auto;justify-content:flex-start;max-width:100%;flex-wrap:nowrap}\n  .tab{flex:none}\n  main{margin:16px auto 40px;padding:0 12px}\n  .card{padding:16px;border-radius:12px}\n  .kpi-grid{gap:10px}\n  .kpi{padding:14px 15px}\n  .kpi-value{font-size:22px}\n  .app-name{width:84px}\n  .app-time{width:56px}\n  .goal-name{width:66px;font-size:12px}\n  .goal-unit{display:none}\n  .sync-note{margin-left:0}\n  /* 手机上没有悬停态，提示框只占位不显示 */\n  .chart-trend .trend-tip{display:none}\n  .day-legend{gap:10px;font-size:11px}\n  .tl-tools input[type=search]{flex:1 1 100%}\n  .inline-form{max-width:100%}\n}\n\n/* ---------- 深色模式 ---------- */\n@media (prefers-color-scheme: dark){\n  :root{\n    --bg:#0a0f1e;\n    --card:#121a2c;\n    --card-2:#18213a;\n    --text:#e9edf8;\n    --text-2:#a9b4ca;\n    --muted:#7d89a3;\n    --line:#1e2740;\n    --line-strong:#2a3552;\n    --primary-soft:rgba(99,102,241,.2);\n    --shadow-sm:0 1px 2px rgba(0,0,0,.5);\n    --shadow-md:0 16px 34px -16px rgba(0,0,0,.75);\n    --heat0:#18213a;--heat1:#2b3768;--heat2:#4b53b5;--heat3:#7c7ff5;\n  }\n  body{\n    background:\n      radial-gradient(1100px 520px at 8% -8%,rgba(79,70,229,.24),transparent 62%),\n      radial-gradient(900px 460px at 102% -4%,rgba(236,72,153,.13),transparent 58%),\n      var(--bg);\n  }\n  .topbar{background:rgba(12,18,33,.78);border-bottom-color:rgba(30,39,64,.9)}\n  .tabs{background:rgba(255,255,255,.045);border-color:rgba(255,255,255,.06)}\n  .tab:hover{background:rgba(255,255,255,.07);color:var(--text)}\n  .tab.active{color:#fff}\n  .kpi::after{background:radial-gradient(circle,rgba(124,127,245,.18),transparent 70%)}\n  .kpi-time .kpi-icon{background:rgba(99,102,241,.22);color:#a5b4fc}\n  .kpi-count .kpi-icon{background:rgba(16,185,129,.2);color:#5eead4}\n  .kpi-apps .kpi-icon{background:rgba(139,92,246,.22);color:#c4b5fd}\n  .kpi-ipad .kpi-icon{background:rgba(245,158,11,.22);color:#fcd34d}\n  button:hover{background:rgba(255,255,255,.06);border-color:var(--line-strong)}\n  .app-bar-wrap{background:rgba(255,255,255,.06);box-shadow:inset 0 1px 2px rgba(0,0,0,.35)}\n  .goal-track{background:rgba(255,255,255,.06);box-shadow:inset 0 1px 2px rgba(0,0,0,.35)}\n  .goal-text{background:rgba(9,14,26,.82);color:#e9edf8;box-shadow:0 1px 3px rgba(0,0,0,.5)}\n  .heat-cell.h0{color:#5f6c86}\n  .heat-cell.h1{color:#c3c8f5}\n  thead th{background:rgba(255,255,255,.035)}\n  tbody tr:hover{background:rgba(124,127,245,.09)}\n  .tag.vivo{background:rgba(16,185,129,.16);color:#5eead4}\n  .tag.ipad{background:rgba(245,158,11,.16);color:#fcd34d}\n  .tag.est{background:rgba(239,68,68,.18);color:#fca5a5}\n  .tag.both{background:rgba(99,102,241,.22);color:#c7d2fe}\n  .warn{background:rgba(245,158,11,.1);border-color:rgba(245,158,11,.2);color:#fcd34d}\n  .info-card{background:rgba(99,102,241,.1);border-color:rgba(99,102,241,.2);color:#c7d2fe}\n  code{background:rgba(124,127,245,.16);color:#c7d2fe}\n  code.block{background:rgba(255,255,255,.045);color:#a5b4fc}\n  .trend-tip{background:#e9edf8;color:#0a0f1e;box-shadow:0 12px 26px -8px rgba(0,0,0,.8)}\n  .result{color:#a5b4fc}\n  .danger-zone{border-color:rgba(239,68,68,.32);background:linear-gradient(180deg,rgba(239,68,68,.07),transparent)}\n  .fresh-banner.warn{background:rgba(239,68,68,.14);border-color:rgba(239,68,68,.32);color:#fca5a5}\n  .kpi-hint{color:#a5b4fc}\n  .kpi-hint.muted{color:#8b97ad}\n  .tl-tools input[type=search]{background:rgba(255,255,255,.05);border-color:rgba(255,255,255,.1);color:var(--text)}\n  .inline-form input[type=text],.inline-form input[type=number]{background:rgba(255,255,255,.05);border-color:rgba(255,255,255,.1);color:var(--text)}\n  button.ghost{border-color:rgba(255,255,255,.12);color:#a9b4c8}\n  button.ghost:hover{background:rgba(124,127,245,.14);color:#c7d2fe}\n  pre.pre{background:rgba(255,255,255,.04);border-color:rgba(255,255,255,.08);color:#a9b4c8}\n  .day-mark{opacity:.8}\n  .tl-block.estimated{border-color:rgba(0,0,0,.55)}\n  ::-webkit-scrollbar-thumb{background:rgba(123,135,154,.4);background-clip:content-box}\n}\n\n/* 安装包下载按钮 */\n.dl-btn{\n  display:inline-flex;align-items:center;gap:8px;padding:11px 18px;\n  background:linear-gradient(135deg,#4f7cff,#7c5cff);color:#fff;\n  border-radius:10px;font-weight:600;font-size:14px;text-decoration:none;\n  box-shadow:0 4px 14px rgba(79,124,255,.3);transition:transform .15s,box-shadow .15s;\n}\n.dl-btn:hover{transform:translateY(-2px);box-shadow:0 6px 20px rgba(79,124,255,.45)}\n.dl-btn:active{transform:translateY(0)}\n\n</style>\n</head>\n<body>\n<header class=\"topbar\">\n  <div class=\"brand\"><span class=\"logo\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7.5V12l3.2 1.9\"/></svg></span> 应用时间看板 <small>vivo X90 + iPad Air 6 · 云端版</small></div>\n  <nav class=\"tabs\">\n    <button class=\"tab active\" data-page=\"dashboard\">看板</button>\n    <button class=\"tab\" data-page=\"analysis\">分析</button>\n    <button class=\"tab\" data-page=\"import\">导入数据</button>\n    <button class=\"tab\" data-page=\"manage\">数据管理</button>\n    <button class=\"tab\" data-page=\"guide\">配置指南</button>\n  </nav>\n</header>\n\n<!-- 数据新鲜度提示：断流时醒目提醒 -->\n<div id=\"fresh-banner\" class=\"fresh-banner\" hidden></div>\n\n<main>\n<!-- ============ 看板页 ============ -->\n<section id=\"page-dashboard\" class=\"page active\">\n  <div class=\"filters card\">\n    <div class=\"filter-item\">\n      <label>统计日期</label>\n      <input type=\"date\" id=\"f-date\">\n    </div>\n    <div class=\"filter-item\">\n      <label>设备</label>\n      <select id=\"f-device\">\n        <option value=\"all\">全部设备</option>\n        <option value=\"vivo_x90\">vivo X90</option>\n        <option value=\"ipad_air6\">iPad Air 6</option>\n      </select>\n    </div>\n    <div class=\"filter-item\">\n      <label>趋势天数</label>\n      <select id=\"f-days\">\n        <option value=\"7\">近 7 天</option>\n        <option value=\"14\">近 14 天</option>\n        <option value=\"30\">近 30 天</option>\n      </select>\n    </div>\n    <div class=\"filter-item\">\n      <label>时长口径</label>\n      <select id=\"f-mode\" title=\"相加＝两台设备时长直接相加（设备投入量）；去重＝同一时刻只算一次（真实占用时间）\">\n        <option value=\"sum\">相加（设备投入）</option>\n        <option value=\"union\">去重（真实占用）</option>\n      </select>\n    </div>\n    <button id=\"btn-refresh\" class=\"primary\">刷新数据</button>\n    <span class=\"sync-note\" id=\"sync-note\"></span>\n  </div>\n\n  <div class=\"kpi-grid\">\n    <div class=\"kpi card kpi-time\">\n      <div class=\"kpi-top\"><span class=\"kpi-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7.5V12l3 2\"/></svg></span><span class=\"kpi-label\">当日总时长</span></div>\n      <div class=\"kpi-value\" id=\"kpi-duration\">--</div>\n    </div>\n    <div class=\"kpi card kpi-count\">\n      <div class=\"kpi-top\"><span class=\"kpi-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M17 2.5 21 6.5l-4 4\"/><path d=\"M3 11.5V9.5a3 3 0 0 1 3-3h15\"/><path d=\"M7 21.5 3 17.5l4-4\"/><path d=\"M21 12.5v2a3 3 0 0 1-3 3H3\"/></svg></span><span class=\"kpi-label\">打开次数</span></div>\n      <div class=\"kpi-value\" id=\"kpi-count\">--</div>\n    </div>\n    <div class=\"kpi card kpi-apps\">\n      <div class=\"kpi-top\"><span class=\"kpi-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"7.5\" height=\"7.5\" rx=\"2\"/><rect x=\"13.5\" y=\"3\" width=\"7.5\" height=\"7.5\" rx=\"2\"/><rect x=\"3\" y=\"13.5\" width=\"7.5\" height=\"7.5\" rx=\"2\"/><rect x=\"13.5\" y=\"13.5\" width=\"7.5\" height=\"7.5\" rx=\"2\"/></svg></span><span class=\"kpi-label\">使用 App 数</span></div>\n      <div class=\"kpi-value\" id=\"kpi-apps\">--</div>\n    </div>\n    <div class=\"kpi card kpi-ipad\">\n      <div class=\"kpi-top\"><span class=\"kpi-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"5\" y=\"2.5\" width=\"14\" height=\"19\" rx=\"2.5\"/><path d=\"M11 18.5h2\"/></svg></span><span class=\"kpi-label\">iPad 时长</span></div>\n      <div class=\"kpi-value\" id=\"kpi-ipad\">--</div>\n    </div>\n  </div>\n  <p class=\"kpi-hint muted\" id=\"kpi-hint\"></p>\n\n  <div class=\"grid-2\">\n    <div class=\"card\">\n      <h2>每日使用时长趋势 <span class=\"hint\">按设备堆叠</span></h2>\n      <div id=\"chart-trend\" class=\"chart-trend\"></div>\n      <div class=\"legend day-legend\"><span><i class=\"dot day-work\"></i>工作日</span><span><i class=\"dot day-rest\"></i>周末</span><span><i class=\"dot day-holiday\"></i>法定假日</span><span><i class=\"dot day-makeup\"></i>调休上班</span></div>\n    </div>\n    <div class=\"card\">\n      <h2>App 时长排行 <span class=\"hint\">当日</span></h2>\n      <div id=\"chart-apps\" class=\"chart-apps\"></div>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h2>时刻热力图 <span class=\"hint\">近 <span id=\"heatmap-days\">7</span> 天 · 按开始时刻统计</span></h2>\n    <div id=\"chart-heatmap\" class=\"heatmap\"></div>\n    <div class=\"legend\"><span>少</span><div class=\"legend-bar\"></div><span>多</span></div>\n  </div>\n\n  <div class=\"card\">\n    <h2>一天时间线 <span class=\"hint\">当日各 App 使用片段</span></h2>\n    <div class=\"tl-tools\">\n      <input type=\"search\" id=\"f-timeline-app\" placeholder=\"只显示某个 App（如 微信）\" spellcheck=\"false\">\n      <span class=\"hint\" id=\"timeline-filter-note\"></span>\n    </div>\n    <div class=\"timeline-legend\">\n      <span><i class=\"dot vivo\"></i>vivo X90</span>\n      <span><i class=\"dot ipad\"></i>iPad Air 6（启用「打开上报」时才有时间线）</span>\n      <span class=\"hint\">虚线边框 = 估算时长</span>\n    </div>\n    <div id=\"chart-timeline\" class=\"timeline\"></div>\n  </div>\n\n  <div class=\"card\">\n    <h2>明细记录 <span class=\"hint\">当日</span></h2>\n    <div class=\"card-actions\">\n      <button id=\"btn-share\" class=\"ghost\">生成分享图</button>\n      <button id=\"btn-share-week\" class=\"ghost\">分享近 7 天</button>\n    </div>\n    <div class=\"table-wrap\">\n      <table id=\"table-detail\">\n        <thead><tr><th>设备</th><th>应用</th><th>开始</th><th>结束</th><th>时长</th><th>来源</th></tr></thead>\n        <tbody></tbody>\n      </table>\n    </div>\n  </div>\n</section>\n\n<!-- ============ 分析页 ============ -->\n<section id=\"page-analysis\" class=\"page\">\n  <div class=\"filters card\">\n    <div class=\"filter-item\">\n      <label>分析区间</label>\n      <select id=\"a-range\">\n        <option value=\"7\">近 7 天</option>\n        <option value=\"14\">近 14 天</option>\n        <option value=\"30\">近 30 天</option>\n      </select>\n    </div>\n    <div class=\"filter-item\">\n      <label>设备</label>\n      <select id=\"a-device\">\n        <option value=\"all\">全部设备</option>\n        <option value=\"vivo_x90\">vivo X90</option>\n        <option value=\"ipad_air6\">iPad Air 6</option>\n      </select>\n    </div>\n    <button id=\"btn-analysis-refresh\" class=\"primary\">重新分析</button>\n    <span class=\"sync-note\" id=\"analysis-note\"></span>\n  </div>\n\n  <div class=\"grid-2\">\n    <div class=\"card\">\n      <h2>分类时间分配 <span class=\"hint\" id=\"a-range-label\">近 7 天</span></h2>\n      <div id=\"chart-category\" class=\"chart-apps\"></div>\n    </div>\n    <div class=\"card\">\n      <h2>周报总结</h2>\n      <div id=\"report\" class=\"report\"></div>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h2>每日目标达成 <span class=\"hint\">点击目标值可修改，保存在本浏览器</span></h2>\n    <div id=\"goals\" class=\"goals\"></div>\n  </div>\n\n  <div class=\"card\">\n    <h2>周对比趋势 <span class=\"hint\">本周 vs 上一周期（按所选天数对齐）</span></h2>\n    <div id=\"chart-compare\" class=\"chart-trend\"></div>\n  </div>\n\n  <div class=\"card narrow\">\n    <h2>分类规则</h2>\n    <p class=\"desc\">App 按名称关键词自动归类，可修改。优先级从上到下，命中即停止。留空的 App 归入\"其他\"。</p>\n    <textarea id=\"rules-editor\" class=\"rules-editor\" spellcheck=\"false\"></textarea>\n    <div class=\"inline-form\" style=\"margin-top:10px\">\n      <button id=\"btn-save-rules\" class=\"primary\">保存规则</button>\n      <button id=\"btn-reset-rules\">恢复默认</button>\n    </div>\n    <div id=\"rules-result\" class=\"result\"></div>\n  </div>\n</section>\n\n<!-- ============ 导入页 ============ -->\n<section id=\"page-import\" class=\"page\">\n  <div class=\"card narrow\">\n    <h2>导入 Android（vivo X90）数据</h2>\n    <p class=\"desc\">在时光口袋（time-pocket）的「口袋」页导出 JSON 备份，然后在本页选择该文件上传。导入为<strong>精确时长</strong>，重复导入会自动去重。文件始终只发往你自己的云端数据库。<br>想省掉手动上传？在手机上配置自动化，把同一份备份直接 POST 到 <code>/api/ingest/android</code>，就能\"导出即上传\"，做法见「配置指南」第四节。</p>\n    <form id=\"form-import\">\n      <input type=\"file\" id=\"import-file\" accept=\".json,application/json\" required>\n      <button type=\"submit\" class=\"primary\">导入备份</button>\n    </form>\n    <div id=\"import-result\" class=\"result\"></div>\n  </div>\n\n  <div class=\"card narrow\">\n    <h2>测试 iPad 日报上报</h2>\n    <p class=\"desc\">模拟一次屏幕时间日报上报，验证云端是否正常工作。可直接粘贴 iPad「获取 App 与网站活动」显示的结果（每行 <code>应用名 (N 小时 M 分钟)</code>），系统已按真实格式适配。</p>\n    <textarea id=\"test-report\" class=\"rules-editor\" style=\"height:90px\" placeholder=\"微信 (1 小时 45 分钟)&#10;抖音 (58 分钟)\">微信 (1 小时 45 分钟)\n抖音 (58 分钟)\nSafari浏览器 (30 分钟)</textarea>\n    <div style=\"margin-top:10px\"><button id=\"btn-test-report\" class=\"primary\">模拟上报日报</button></div>\n    <div id=\"test-result\" class=\"result\"></div>\n  </div>\n\n  <div class=\"card narrow danger-zone\">\n    <h2>清空数据</h2>\n    <p class=\"desc\">删除云端全部已导入和上报的记录，不可恢复。</p>\n    <button id=\"btn-reset\" class=\"danger\">清空全部数据</button>\n  </div>\n</section>\n\n<!-- ============ 数据管理页 ============ -->\n<section id=\"page-manage\" class=\"page\">\n  <div class=\"card narrow\">\n    <h2>云端状态</h2>\n    <p class=\"desc\">数据存在你自己的 Cloudflare D1 数据库里。这里可以查看数据量、导出备份、清理旧数据、测试推送。</p>\n    <div id=\"manage-status\" class=\"manage-status\">加载中...</div>\n  </div>\n\n  <div class=\"card narrow\">\n    <h2>导出备份 <span class=\"hint\">建议每月导出一次</span></h2>\n    <p class=\"desc\">导出的 JSON 与 time-pocket 备份格式兼容，可直接拷回手机恢复；CSV 用 Excel 打开即可做透视分析。导出链接需要同步令牌（如果在 4.1 里设过）。</p>\n    <div class=\"inline-form\">\n      <input type=\"text\" id=\"export-token\" placeholder=\"同步令牌（没设置可留空）\" spellcheck=\"false\">\n      <button id=\"btn-export-json\" class=\"primary\">导出 JSON</button>\n      <button id=\"btn-export-csv\">导出 CSV</button>\n    </div>\n    <div id=\"export-result\" class=\"result\"></div>\n  </div>\n\n  <div class=\"card narrow\">\n    <h2>数据保留与清理 <span class=\"hint\">超出保留期的记录会被删除</span></h2>\n    <p class=\"desc\">默认保留 540 天。清理不可恢复，<strong>建议先导出再清理</strong>。可以先试运行看看会删多少。</p>\n    <div class=\"inline-form\">\n      <label class=\"inline-label\">保留天数</label>\n      <input type=\"number\" id=\"cleanup-days\" value=\"540\" min=\"0\" step=\"1\">\n      <button id=\"btn-cleanup-dry\">试运行</button>\n      <button id=\"btn-cleanup\" class=\"danger\">执行清理</button>\n    </div>\n    <div id=\"cleanup-result\" class=\"result\"></div>\n  </div>\n\n  <div class=\"card narrow\">\n    <h2>每日推送摘要 <span class=\"hint\">手机主动收到昨日小结</span></h2>\n    <p class=\"desc\">配置好 Cloudflare 的推送渠道后，Worker 每天定时把昨日总时长、Top5 应用和环比变化推送到手机，不用打开看板。</p>\n    <ol class=\"steps\">\n      <li>Cloudflare → Worker → <strong>Settings → Variables and Secrets</strong>，添加：<br>\n        <code class=\"block\">PUSH_WEBHOOK = 你的推送地址</code>\n        <code class=\"block\">PUSH_TYPE = bark（默认）/ serverchan / telegram</code>\n        Telegram 还需要 <code class=\"block\">PUSH_CHAT_ID = 你的 chat id</code></li>\n      <li><strong>Settings → Triggers → Cron Triggers → Add</strong>，cron 填 <code>0 1 * * *</code>（UTC 1 点 = 北京时间每天 9 点）。</li>\n      <li>填好后在下面点「测试推送」，确认手机能收到。</li>\n    </ol>\n    <div class=\"inline-form\">\n      <input type=\"text\" id=\"push-token\" placeholder=\"同步令牌\" spellcheck=\"false\">\n      <button id=\"btn-push-test\">测试推送</button>\n    </div>\n    <div id=\"push-result\" class=\"result\"></div>\n  </div>\n</section>\n\n<!-- ============ 配置指南页 ============ -->\n<section id=\"page-guide\" class=\"page\">\n  <div class=\"card narrow\">\n    <h2>一、部署到 Cloudflare（手机浏览器，一次性）</h2>\n    <ol class=\"steps\">\n      <li>手机浏览器打开 <a href=\"https://dash.cloudflare.com\" target=\"_blank\">dash.cloudflare.com</a>，注册并登录（邮箱即可）。</li>\n      <li>左侧 <strong>Workers &amp; Pages → Create → Create Worker</strong>，随便命名（如 <code>app-time</code>），点 <strong>Deploy</strong>。</li>\n      <li>进入该 Worker，点 <strong>Edit code</strong>，把默认代码全部删除，粘贴 <code>worker.js</code> 的完整内容，点 <strong>Deploy</strong>。</li>\n      <li>左侧 <strong>D1 SQL Database → Create database</strong>，名称填 <code>usage-db</code>，创建。</li>\n      <li>点开这个数据库 → <strong>Console</strong>，把 <code>schema.sql</code> 的内容整段粘贴执行，建立数据表。</li>\n      <li>回到你的 Worker → <strong>Settings → Bindings → Add binding → D1 database</strong>，变量名填 <code>DB</code>，选择 <code>usage-db</code>，保存。</li>\n      <li>浏览器访问你的 Worker 地址（形如 <code>https://app-time.你的账号.workers.dev</code>），看到看板即部署成功。<strong>把这个地址记下来，下面两台设备都要用。</strong></li>\n    </ol>\n    <p class=\"warn\">⚠️ 若国内偶尔打不开 <code>workers.dev</code>，可在 Workers 的 Settings → Triggers 里绑定一个自己的自定义域名（需已有域名）。绝大多数情况下直连即可用。</p>\n  </div>\n\n  <div class=\"card narrow\">\n    <h2>二、Android（vivo X90）配置</h2>\n    <ol class=\"steps\">\n      <li>从源码构建 time-pocket 并安装到手机（项目地址见交付说明）。</li>\n      <li>打开应用，在「口袋」中开启<strong>使用情况访问权限</strong>。</li>\n      <li>vivo 手机请在「设置 → 电池 → 后台高耗电 / 自启动」中允许 time-pocket 后台运行，避免漏采。</li>\n      <li>推荐安装<strong>「自动同步版」</strong>（第四节 4.2）：采集后自动上传，不用再手动导出。若用原版，则在「口袋」页导出 JSON 备份后到看板「导入数据」页上传。</li>\n    </ol>\n  </div>\n\n  <div class=\"card narrow\">\n    <h2>三、iPad Air 6 配置（iOS 26 屏幕时间 · 推荐）</h2>\n    <p class=\"desc\">利用 iPadOS 26 新增的「获取 App 与网站活动」动作，直接读取系统「屏幕使用时间」里每个 App 的<strong>精确时长</strong>，每天自动上报一次。不用再为每个 App 建自动化。</p>\n    <div class=\"info-card\">\n      ✅ 已在你的 iPad 上实测：该动作返回的是<strong>纯文本</strong>，每行形如 <code>微信 (1 小时 45 分钟)</code>。看板已<strong>按此真实格式适配</strong>，把结果原样发上来即可，无需拼 JSON。\n    </div>\n    <ol class=\"steps\">\n      <li>确认系统：设置 → 通用 → 关于本机，iPadOS <strong>26 或更新</strong>。若更低，先免费升级。</li>\n      <li>开启统计：设置 → <strong>屏幕时间</strong> → App 与网站活动 → 打开「查看所有 App 与网站活动」（要确保系统本身在记录）。</li>\n      <li>打开 <strong>「快捷指令」</strong> App → 右上角 <strong>+</strong> 新建快捷指令，命名如「上报屏幕时间」。</li>\n      <li>添加动作 <strong>「获取 App 与网站活动」</strong>，日期选 <strong>「昨天」</strong>。（你实测时选的是\"今天\"，正式用请选\"昨天\"，数据才完整。）</li>\n      <li>添加动作 <strong>「获取 URL 内容」</strong>：URL 填 <code class=\"block\">https://app-time.你的账号.workers.dev/api/ipad/daily</code>（域名换成你自己的；若按第四节设置了同步令牌，结尾再加 <code>?k=你的令牌</code>）；方法选 <strong>POST</strong>；请求体类型选 <strong>文本</strong>，内容直接放上一步「获取 App 与网站活动」的结果变量。<br>\n        <span class=\"muted-text\">这样发出去的内容就是你实测看到的那种 <code>微信 (1 小时 45 分钟)</code> 多行文本，看板能直接识别。</span></li>\n      <li>再到 <strong>「自动化」</strong> → 创建个人自动化 → 触发器选 <strong>「特定时间」</strong>（如每天 08:00）→ 添加操作选刚建的「上报屏幕时间」→ <strong>关闭「运行前询问」</strong>。之后每天自动把昨天的数据存入看板。</li>\n    </ol>\n    <p class=\"warn\">⚠️ <strong>实测结论</strong>：屏幕时间这个动作只给<strong>每个 App 当日总时长</strong>——你在设置里看到的<strong>按小时柱状图和\"拿起次数\"读不出来</strong>，所以看板 iPad 端没有单次时刻、次数和小时热力图，时间线/热力图只反映 vivo 端。系统只保留约 <strong>4 周</strong>明细，记录从你开始配置那天起往前攒。若上报后看板无数据，先在「导入数据」页用「测试 iPad 日报上报」验证服务（把实测那段文本粘进去点一下即可）。</p>\n    <p class=\"desc\">旧的「打开 App 时上报」接口 <code>/api/ipad/event</code> 仍保留兼容。若你想回到按次上报（可看时刻和次数、但时长为估算），把某条自动化改用旧接口即可。若上报失败，浏览器打开 <code>https://你的域名/api/health</code> 返回 <code>{\"ok\":true}</code> 即服务正常。</p>\n  </div>\n\n  <div class=\"card narrow\">\n    <h2>四、让数据自动进来</h2>\n    <p class=\"desc\">两台设备的自动化程度不一样，先看结论：</p>\n    <table>\n      <thead><tr><th>设备</th><th>能否全自动</th><th>说明</th></tr></thead>\n      <tbody>\n        <tr><td>iPad Air 6</td><td><strong>能</strong></td><td>按第三节建好每日定时自动化即可，之后完全不用管。</td></tr>\n        <tr><td>vivo X90</td><td><strong>能</strong>（装自动同步版）</td><td>原版 time-pocket 只能手动导出，所以改了一版：采集后自动上传，不用再点导出。详见 4.2。</td></tr>\n      </tbody>\n    </table>\n\n    <h3 class=\"sub\">4.1 先给写入接口加把锁（推荐，1 分钟）</h3>\n    <p class=\"desc\">开启自动化后，写数据的链接会存在手机里，建议加一个令牌，防止网址被别人知道后写入或清空数据：</p>\n    <ol class=\"steps\">\n      <li>Cloudflare → 你的 Worker → <strong>Settings → Variables and Secrets（变量与密钥）</strong> → 添加一个变量，名称填 <code>SYNC_TOKEN</code>，值随便编一串（如 <code>mytime-8f3a</code>），保存后 <strong>Deploy</strong> 生效。</li>\n      <li>之后所有写入链接都要带上 <code>?k=你的令牌</code>（也可以用请求头 <code>X-Sync-Token</code>）——包括 iPad 快捷指令的 <code>/api/ipad/daily?k=令牌</code>。<strong>看板浏览不受影响</strong>，只有写入需要令牌。</li>\n      <li>没设置令牌也能正常用，只是任何人都能往你的库里写，建议设一个。</li>\n    </ol>\n\n    <h3 class=\"sub\">4.2 vivo：装「自动同步版」时光口袋（推荐，配一次永久自动）</h3>\n    <p class=\"desc\">原版 time-pocket 没有联网能力，所以我直接改了一份：<strong>每次后台采集（约 15 分钟）后，自动把新记录推到看板</strong>，你什么都不用点。</p>\n    <p class=\"desc\"><a class=\"dl-btn\" href=\"/app.apk\" download>⬇️ 点此下载安装包（时光口袋-自动同步版.apk · 120KB）</a></p>\n    <div class=\"warn\">⚠️ <strong>先备份再安装</strong>：如果你手机上装的是从应用商店或 GitHub 装的原版，签名和这个包不同，<strong>必须先卸载再安装</strong>。卸载会清空本地记录，所以务必先在旧版「导出本地备份」存到手机里，装好新版再用「从文件恢复」找回来。<br>但<strong>这个自动同步版以后可以随便升级</strong>：它用的是固定签名（<code>time-pocket-release.jks</code>），新版本直接覆盖安装即可，不会丢数据、不用再备份。</div>\n    <ol class=\"steps\">\n      <li>旧版：我的口袋 → 备份与数据 → <strong>导出本地备份</strong>，存到「下载」。</li>\n      <li>卸载旧版，安装 <code>时光口袋-自动同步版.apk</code>（需允许安装未知来源应用）。</li>\n      <li>打开新版 → 我的口袋 → 备份与数据 → 点 <strong>「自动同步看板」</strong>。</li>\n      <li>地址填 <code>https://你的域名/api/ingest/android</code>，令牌填 4.1 里设的 <code>SYNC_TOKEN</code>（没设就留空），点 <strong>「立即同步」</strong>。</li>\n      <li>看到「已上传 N 条使用记录」就成功了；刷新看板，右上角会变成「vivo 刚刚」。之后每 15 分钟自动同步，不用再管。</li>\n      <li>最后点「从文件恢复」把第 1 步的备份导回来，历史数据（含手记和图片）全部还原。</li>\n    </ol>\n    <div class=\"info-card\"><strong>它上传什么：</strong>只有应用名和使用时段，不含手记、图片和原始事件，单次几十 KB。另外每天在本机留一份完整备份（<code>Android/data/cn.timepocket.app/files/auto-backup</code>，保留 7 天）。</div>\n    <p class=\"desc\"><strong>传错了怎么办：</strong>「我的口袋 → 备份与数据 → <strong>补传全部历史</strong>」可以把本地所有记录重新推一遍（服务端按「设备+应用+开始时间」去重，重复推送不会产生重复数据）。刚配好地址、或怀疑历史没传全时用它。</p>\n    <p class=\"desc\"><strong>网络断了也不会丢数据：</strong>上传失败的片段会存进本地待传队列（<code>Android/data/cn.timepocket.app/files/sync-pending.json</code>），下次联网自动重传；连续失败时按 15 分钟 → 1 小时 → 6 小时退避，不会反复打扰服务端。设置页会显示「N 条待重传」。</p>\n\n    <h3 class=\"sub\">4.3 备选：不改 App 的做法</h3>\n    <p class=\"desc\">如果你更愿意用原版 time-pocket，就靠手机上的自动化工具把导出文件推上去：</p>\n    <ul class=\"desc\">\n      <li><strong>MacroDroid</strong>：触发器「文件变化」选导出文件夹（或「定时」每 6 小时）→ 动作「读取文件文本」→「HTTP 请求」POST 到\n        <code class=\"block\">https://你的域名/api/ingest/android?k=你的令牌</code>\n        Content-Type 填 <code>application/json</code>，请求体放读到的文本。</li>\n      <li><strong>Termux（命令行）</strong>：\n        <code class=\"block\">curl -X POST \"https://你的域名/api/ingest/android?k=令牌\" \\\n  -H \"Content-Type: application/json\" \\\n  --data-binary @/sdcard/Download/备份文件.json</code>\n        再用 <code>termux-job-scheduler</code> 设成定时任务。</li>\n      <li><strong>HTTP Request Shortcuts</strong>（开源免费）：建成桌面快捷方式，点一下上传。</li>\n    </ul>\n    <div class=\"info-card\"><strong>提示：重复推送同一份备份是安全的。</strong>云端按「设备 + 应用 + 开始时间 + 来源」去重，定时反复推不会产生重复数据。</div>\n\n    <h3 class=\"sub\">4.4 怎么确认真的自动了</h3>\n    <p class=\"desc\">看板右上角会显示 <strong>vivo 3 小时前 · iPad 12 分钟前</strong> 这样的同步状态（点小圆点可看精确时间）。如果 vivo 一直是\"未同步\"，说明自动化没跑起来，多半是被系统省电策略拦了，回去检查自启动和后台权限。</p>\n  </div>\n\n  <div class=\"card narrow\">\n    <h2>六、装到手机上像 App 一样用（PWA）</h2>\n    <p class=\"desc\">看板已经做成 PWA，可以\"添加到主屏幕\"，打开时全屏、没有浏览器地址栏，断网也能看到上次的数据。</p>\n    <ol class=\"steps\">\n      <li><strong>iPad（Safari）</strong>：打开看板网址 → 点底部/顶部的<strong>分享</strong>按钮 → 选<strong>「添加到主屏幕」</strong> → 完成。桌面上会出现一个时钟图标，点开即全屏运行。</li>\n      <li><strong>vivo（Chrome / 自带浏览器）</strong>：打开看板网址 → 右上角<strong>菜单</strong> → <strong>「添加到主屏幕」</strong>或「安装应用」。</li>\n      <li>添加后可以离线打开：已浏览过的页面照常显示，联网后自动刷新最新数据。</li>\n    </ol>\n    <p class=\"desc\"><strong>每天收到小结：</strong>不想每次都主动打开看板，可以配一条定时推送——在 <strong>Worker → Settings → Variables and Secrets</strong> 里加 <code>PUSH_WEBHOOK</code>（你的推送地址）和 <code>PUSH_TYPE</code>（<code>bark</code> / <code>serverchan</code> / <code>telegram</code>），再到 <strong>Settings → Triggers → Cron Triggers</strong> 加 <code>0 1 * * *</code>，每天北京时间 9 点就会把昨日总时长、Top5 应用和环比变化推到手机上。配好后可在「数据管理」页点「测试推送」验证。</p>\n  </div>\n\n  <div class=\"card narrow\">\n    <h2>五、数据口径说明</h2>\n    <ul class=\"desc\">\n      <li><strong>vivo X90</strong>：来自 time-pocket 的 <code>sessions</code>，每条为一次前台使用片段，时长、时刻、次数都精确。</li>\n      <li><strong>iPad Air 6</strong>：默认来自系统「屏幕时间」的每日汇总（<code>source=screen_time</code>），<strong>时长为系统精确值</strong>，但无单次时刻和次数；同一天重复上报会覆盖更新。若用旧版打开上报，则时长为估算、有用时刻和次数。</li>\n      <li>同一个 App 在两台设备上会<strong>合并成一行</strong>并标注「双设备」——安卓按包名（<code>com.tencent.mm</code>）识别，iPad 按名称（微信）识别，看板用应用名把它们对齐。</li>\n      <li><strong>两种时长口径</strong>：看板右上角可切换。\n        <ul>\n          <li><strong>相加（设备投入）</strong>：两台设备的时长直接相加。同一个时段两台都在用会算两次。</li>\n          <li><strong>去重（真实占用）</strong>：按时间区间做并集，同一时段只算一次，更接近\"你实际盯着屏幕多久\"。</li>\n        </ul>\n        注意：iPad 的屏幕时间日报只有当日总量、没有分布时刻，<strong>无法参与去重</strong>，这部分仍按原值计入，看板会明确标出。</li>\n      <li>小于 <strong>10 秒</strong>的片段视为误触，默认不计入统计。</li>\n      <li>趋势图日期下方的小圆点标记了<strong>工作日 / 周末 / 法定假日 / 调休上班</strong>（含 2026 年国务院公布的调休安排），方便对比效率。</li>\n      <li>所有数据保存在<strong>你自己的 Cloudflare D1 数据库</strong>，不经过任何第三方中转。所有时间按北京时间（GMT+8）统计。</li>\n    </ul>\n  </div>\n</section>\n</main>\n\n<script>\n\"use strict\";\n\nconst $ = (sel) => document.querySelector(sel);\nconst $$ = (sel) => Array.from(document.querySelectorAll(sel));\n\nfunction fmtDuration(ms) {\n  if (!ms || ms <= 0) return \"0分\";\n  const min = Math.round(ms / 60000);\n  if (min < 60) return min + \"分\";\n  const h = Math.floor(min / 60);\n  const m = min % 60;\n  return m ? `${h}小时${m}分` : `${h}小时`;\n}\nfunction fmtShort(ms) {\n  if (!ms || ms <= 0) return \"0m\";\n  const min = Math.round(ms / 60000);\n  return min >= 60 ? `${(min / 60).toFixed(1)}h` : `${min}m`;\n}\nfunction fmtClock(ms) {\n  const d = new Date(ms + 8 * 3600 * 1000); // 北京时间\n  return `${String(d.getUTCHours()).padStart(2, \"0\")}:${String(d.getUTCMinutes()).padStart(2, \"0\")}`;\n}\nfunction todayStr() {\n  const d = new Date(Date.now() + 8 * 3600 * 1000);\n  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, \"0\")}-${String(d.getUTCDate()).padStart(2, \"0\")}`;\n}\nasync function api(path, options) {\n  const res = await fetch(path, options);\n  const data = await res.json();\n  if (!res.ok) throw new Error(data.message || \"请求失败\");\n  return data;\n}\n\n/* ---------- 页面切换 ---------- */\n$$(\".tab\").forEach((btn) => {\n  btn.addEventListener(\"click\", () => {\n    $$(\".tab\").forEach((b) => b.classList.remove(\"active\"));\n    $$(\".page\").forEach((p) => p.classList.remove(\"active\"));\n    btn.classList.add(\"active\");\n    $(\"#page-\" + btn.dataset.page).classList.add(\"active\");\n  });\n});\n\n/* ---------- 筛选 ---------- */\n$(\"#f-date\").value = todayStr();\n$(\"#btn-refresh\").addEventListener(\"click\", loadDashboard);\n$(\"#f-device\").addEventListener(\"change\", loadDashboard);\n$(\"#f-days\").addEventListener(\"change\", loadDashboard);\n$(\"#f-mode\").addEventListener(\"change\", () => {\n  localStorage.setItem(\"time_mode\", $(\"#f-mode\").value);\n  loadDashboard();\n});\n// 记住上次选择的口径\n$(\"#f-mode\").value = localStorage.getItem(\"time_mode\") || \"sum\";\n\nfunction currentFilters() {\n  return {\n    date: $(\"#f-date\").value || todayStr(),\n    device: $(\"#f-device\").value,\n    days: parseInt($(\"#f-days\").value, 10),\n    mode: $(\"#f-mode\").value,\n  };\n}\n\n/* ---------- 时间轴 App 筛选 ---------- */\nlet timelineRows = [];\nlet timelineDate = \"\";\n$(\"#f-timeline-app\").addEventListener(\"input\", () => {\n  renderTimeline(timelineRows, timelineDate, $(\"#f-device\").value);\n});\n\n/* ---------- 加载并渲染 ---------- */\nfunction fmtAgo(ms) {\n  if (!ms) return \"未同步\";\n  const diff = Date.now() - ms;\n  if (diff < 60000) return \"刚刚\";\n  const m = Math.floor(diff / 60000);\n  if (m < 60) return m + \" 分钟前\";\n  const h = Math.floor(m / 60);\n  if (h < 24) return h + \" 小时前\";\n  return Math.floor(h / 24) + \" 天前\";\n}\n\nasync function renderSyncNote() {\n  const el = $(\"#sync-note\");\n  try {\n    const st = await api(\"/api/status\");\n    const a = st.last_sync && st.last_sync.android;\n    const i = st.last_sync && st.last_sync.ipad;\n    const tip = (t) => (t ? new Date(t).toLocaleString(\"zh-CN\") : \"还没有数据\");\n    el.innerHTML =\n      `<i class=\"dot vivo\" title=\"vivo 上次同步：${tip(a)}\"></i>vivo ${fmtAgo(a)}` +\n      `<span class=\"sync-sep\">·</span>` +\n      `<i class=\"dot ipad\" title=\"iPad 上次同步：${tip(i)}\"></i>iPad ${fmtAgo(i)}`;\n    renderFreshBanner(st);\n  } catch (e) {\n    el.textContent = \"\";\n  }\n}\n\n/* 数据新鲜度：任一设备超过 48 小时没同步就醒目提醒 */\nfunction renderFreshBanner(st) {\n  const el = $(\"#fresh-banner\");\n  if (!el) return;\n  const now = Date.now();\n  const items = [];\n  const android = st.last_sync && st.last_sync.android;\n  const ipad = st.last_sync && st.last_sync.ipad;\n  // 只在\"该设备确实有数据、但很久没更新\"时提醒，避免刚上手时满屏警告\n  const hasData = (st.devices || []).length > 0;\n  const check = (name, ts, devKey) => {\n    const dev = (st.devices || []).find((d) => d.device === devKey);\n    if (!ts) {\n      if (dev && dev.n > 0) items.push({ text: `${name}已导入 ${dev.n} 条记录，但从未同步过` });\n      return;\n    }\n    const hours = (now - ts) / 3600000;\n    if (hours > 48) items.push({ text: `${name}已 ${Math.floor(hours)} 小时没有同步` });\n  };\n  check(\"vivo\", android, \"vivo_x90\");\n  check(\"iPad\", ipad, \"ipad_air6\");\n  if (!items.length || !hasData) { el.hidden = true; el.innerHTML = \"\"; return; }\n  el.hidden = false;\n  el.className = \"fresh-banner warn\";\n  el.innerHTML =\n    `<span class=\"fb-icon\">⚠</span><span>${items.map((i) => i.text).join(\"；\")}。` +\n    `看板数据可能不完整，请检查自动上传是否被系统拦截（见「配置指南」第四节）。</span>`;\n}\n\nasync function loadDashboard() {\n  const { date, device, days, mode } = currentFilters();\n  $(\"#sync-note\").textContent = \"\";\n  try {\n    const qs = `device=${device}&mode=${mode}`;\n    const [summary, trend, heatmap, timeline] = await Promise.all([\n      api(`/api/summary?date=${date}&${qs}`),\n      api(`/api/trend?days=${days}&${qs}`),\n      api(`/api/heatmap?days=${days}&${qs}`),\n      api(`/api/timeline?date=${date}&${qs}`),\n    ]);\n    renderKpi(summary);\n    renderTrend(trend);\n    renderApps(summary);\n    renderHeatmap(heatmap, days);\n    timelineRows = timeline;\n    timelineDate = date;\n    renderTimeline(timeline, date, device);\n    renderDetail(timeline);\n    renderSyncNote();\n  } catch (e) {\n    $(\"#sync-note\").textContent = \"加载失败：\" + e.message;\n  }\n}\n\nfunction renderKpi(s) {\n  $(\"#kpi-duration\").textContent = fmtDuration(s.kpi.total_ms);\n  $(\"#kpi-count\").textContent = s.kpi.open_count;\n  $(\"#kpi-apps\").textContent = s.kpi.app_count;\n  // iPad 时长：后端按设备精确累加（避免同名 App 跨设备合并导致的不准）\n  $(\"#kpi-ipad\").textContent = fmtDuration(s.kpi.ipad_ms || 0);\n  // 口径提示：去重模式说明扣掉了多少；相加模式说明这是设备投入量\n  const hint = $(\"#kpi-hint\");\n  if (!hint) return;\n  if (s.mode === \"union\") {\n    const saved = (s.kpi.sum_ms || 0) - (s.kpi.total_ms || 0);\n    hint.textContent = saved > 60000\n      ? `去重口径：两台设备同时使用的 ${fmtDuration(saved)} 只算了一次${s.kpi.daily_ms ? `；iPad 日报 ${fmtDuration(s.kpi.daily_ms)} 无时刻信息，未参与去重` : \"\"}`\n      : \"去重口径：当前没有跨设备重叠时段\";\n    hint.className = \"kpi-hint\";\n  } else {\n    hint.textContent = \"相加口径：两台设备的时长直接相加，代表设备投入量。切到「去重」可看真实占用时间。\";\n    hint.className = \"kpi-hint muted\";\n  }\n}\n\n/* 节假日类型：本地内联一份，避免额外请求 */\nconst DAY_TYPES = (() => {\n  const holidays = [\n    [\"2026-01-01\", \"2026-01-03\"], [\"2026-02-15\", \"2026-02-23\"], [\"2026-04-04\", \"2026-04-06\"],\n    [\"2026-05-01\", \"2026-05-05\"], [\"2026-06-19\", \"2026-06-21\"], [\"2026-09-25\", \"2026-09-27\"],\n    [\"2026-10-01\", \"2026-10-07\"],\n  ];\n  const makeups = [\"2026-01-04\", \"2026-02-14\", \"2026-02-28\", \"2026-05-09\", \"2026-09-20\", \"2026-10-10\"];\n  const names = { \"2026-01-01\": \"元旦\", \"2026-02-17\": \"春节\", \"2026-04-05\": \"清明\", \"2026-05-01\": \"劳动节\", \"2026-06-19\": \"端午\", \"2026-09-25\": \"中秋\", \"2026-10-01\": \"国庆\" };\n  return function (dateStr) {\n    for (const [a, b] of holidays) {\n      if (dateStr >= a && dateStr <= b) {\n        const hit = holidays.find(([x, y]) => dateStr >= x && dateStr <= y);\n        return { type: \"holiday\", label: names[hit[0]] || \"法定假日\" };\n      }\n    }\n    if (makeups.includes(dateStr)) return { type: \"makeup\", label: \"调休上班\" };\n    const d = new Date(Date.parse(dateStr + \"T12:00:00+08:00\"));\n    const w = d.getUTCDay();\n    if (w === 0 || w === 6) return { type: \"rest\", label: \"周末\" };\n    return { type: \"work\", label: \"工作日\" };\n  };\n})();\n\nfunction renderTrend(rows) {\n  const el = $(\"#chart-trend\");\n  el.innerHTML = \"\";\n  if (!rows.length) { el.innerHTML = '<div class=\"empty\">暂无数据</div>'; return; }\n  const max = Math.max(...rows.map((r) => r.duration_ms), 1);\n  rows.forEach((r) => {\n    const col = document.createElement(\"div\");\n    col.className = \"trend-col\";\n    const stack = document.createElement(\"div\");\n    stack.className = \"trend-stack\";\n    const vivo = r.by_device.vivo_x90 ? r.by_device.vivo_x90.duration_ms : 0;\n    const ipad = r.by_device.ipad_air6 ? r.by_device.ipad_air6.duration_ms : 0;\n    const total = vivo + ipad;\n    const h = Math.max((total / max) * 170, total ? 3 : 0);\n    stack.style.height = h + \"px\";\n    if (vivo) {\n      const seg = document.createElement(\"div\");\n      seg.className = \"trend-seg vivo\";\n      seg.style.height = (vivo / total * 100) + \"%\";\n      stack.appendChild(seg);\n    }\n    if (ipad) {\n      const seg = document.createElement(\"div\");\n      seg.className = \"trend-seg ipad\";\n      seg.style.height = (ipad / total * 100) + \"%\";\n      stack.appendChild(seg);\n    }\n    const tip = document.createElement(\"div\");\n    tip.className = \"trend-tip\";\n    const day = DAY_TYPES(r.date);\n    tip.textContent = `${r.date}（${day.label}）  共 ${fmtDuration(r.duration_ms)} · 打开 ${r.count} 次`;\n    const label = document.createElement(\"div\");\n    label.className = \"trend-label\";\n    label.textContent = r.date.slice(5);\n    // 日期标签下方加一个圆点标记工作日 / 休息日 / 法定假日\n    const mark = document.createElement(\"i\");\n    mark.className = \"day-mark \" + day.type;\n    mark.title = day.label;\n    label.appendChild(mark);\n    col.appendChild(tip);\n    col.appendChild(stack);\n    col.appendChild(label);\n    el.appendChild(col);\n  });\n}\n\nfunction renderApps(s) {\n  const el = $(\"#chart-apps\");\n  el.innerHTML = \"\";\n  const apps = s.apps;\n  if (!apps.length) { el.innerHTML = '<div class=\"empty\">当日暂无数据</div>'; return; }\n  const max = Math.max(...apps.map((a) => a.duration_ms), 1);\n  apps.forEach((a) => {\n    const row = document.createElement(\"div\");\n    row.className = \"app-row\";\n    const name = document.createElement(\"div\");\n    name.className = \"app-name\";\n    name.textContent = a.label;\n    name.title = a.key;\n    const wrap = document.createElement(\"div\");\n    wrap.className = \"app-bar-wrap\";\n    const bar = document.createElement(\"div\");\n    bar.className = \"app-bar \" + (a.device === \"vivo_x90\" ? \"vivo\" : (a.device === \"both\" ? \"both\" : \"ipad\"));\n    bar.style.width = Math.max((a.duration_ms / max) * 100, 2) + \"%\";\n    wrap.appendChild(bar);\n    const time = document.createElement(\"div\");\n    time.className = \"app-time\";\n    time.textContent = fmtShort(a.duration_ms);\n    if (a.device === \"both\") {\n      name.innerHTML += ' <span class=\"tag both\">双设备</span>';\n      name.title = (a.key || \"\") + \"（两台设备都有使用）\";\n    }\n    row.appendChild(name);\n    row.appendChild(wrap);\n    row.appendChild(time);\n    el.appendChild(row);\n  });\n}\n\nfunction renderHeatmap(hours, days) {\n  $(\"#heatmap-days\").textContent = days;\n  const el = $(\"#chart-heatmap\");\n  el.innerHTML = \"\";\n  const max = Math.max(...hours.map((h) => h.duration_ms), 1);\n  hours.forEach((h) => {\n    const cell = document.createElement(\"div\");\n    const ratio = h.duration_ms / max;\n    const cls = h.duration_ms === 0 ? \"h0\" : ratio < 0.25 ? \"h1\" : ratio < 0.6 ? \"h2\" : \"h3\";\n    cell.className = \"heat-cell \" + cls;\n    cell.textContent = String(h.hour).padStart(2, \"0\");\n    cell.title = `${String(h.hour).padStart(2, \"0\")}:00  ${fmtDuration(h.duration_ms)} · ${h.count} 次`;\n    el.appendChild(cell);\n  });\n}\n\nfunction renderTimeline(rows, date, device) {\n  const el = $(\"#chart-timeline\");\n  el.innerHTML = \"\";\n  const dayStart = Date.parse(date + \"T00:00:00+08:00\");\n  const spans = device === \"all\" ? [\"vivo_x90\", \"ipad_air6\"] : [device];\n  // 按 App 名筛选（大小写不敏感，支持部分匹配）\n  const kw = ($(\"#f-timeline-app\").value || \"\").trim().toLowerCase();\n  const filtered = kw\n    ? rows.filter((r) => (r.app_label || \"\").toLowerCase().includes(kw))\n    : rows;\n  const note = $(\"#timeline-filter-note\");\n  if (note) note.textContent = kw ? `已筛选「${kw}」，${filtered.length}/${rows.length} 条` : \"\";\n  spans.forEach((dev, idx) => {\n    const lane = document.createElement(\"div\");\n    lane.className = \"tl-lane\";\n    const label = document.createElement(\"div\");\n    label.className = \"tl-lane-label\";\n    label.textContent = dev === \"vivo_x90\" ? \"vivo X90\" : \"iPad Air 6\";\n    const track = document.createElement(\"div\");\n    track.className = \"tl-track\";\n    const items = filtered.filter((r) => r.device === dev);\n    items.forEach((r) => {\n      const left = ((r.clip_start_ms - dayStart) / 86400000) * 100;\n      const width = Math.max((r.clip_duration_ms / 86400000) * 100, 0.2);\n      const block = document.createElement(\"div\");\n      block.className = \"tl-block \" + (dev === \"vivo_x90\" ? \"vivo\" : \"ipad\") + (r.estimated ? \" estimated\" : \"\");\n      block.style.left = left + \"%\";\n      block.style.width = width + \"%\";\n      block.textContent = r.app_label;\n      block.title = `${r.app_label}  ${fmtClock(r.clip_start_ms)} - ${fmtClock(r.clip_end_ms)}  ${fmtDuration(r.clip_duration_ms)}${r.estimated ? \"（估算）\" : \"\"}`;\n      track.appendChild(block);\n    });\n    if (!items.length) {\n      const note = document.createElement(\"div\");\n      note.className = \"tl-empty\";\n      note.textContent = kw ? \"该设备无匹配记录\" : \"当日无使用片段\";\n      track.appendChild(note);\n    }\n    lane.appendChild(label);\n    lane.appendChild(track);\n    // 时间轴只在最后一条泳道显示一次，避免重复\n    if (idx === spans.length - 1) {\n      const axis = document.createElement(\"div\");\n      axis.className = \"tl-axis\";\n      [\"00:00\", \"06:00\", \"12:00\", \"18:00\", \"24:00\"].forEach((t) => {\n        const s = document.createElement(\"span\");\n        s.textContent = t;\n        axis.appendChild(s);\n      });\n      lane.appendChild(axis);\n    }\n    el.appendChild(lane);\n  });\n}\n\nfunction renderDetail(rows) {\n  const tbody = $(\"#table-detail tbody\");\n  tbody.innerHTML = \"\";\n  if (!rows.length) {\n    tbody.innerHTML = '<tr><td colspan=\"6\" class=\"empty\">当日暂无记录</td></tr>';\n    return;\n  }\n  rows.slice().reverse().forEach((r) => {\n    const tr = document.createElement(\"tr\");\n    const dev = r.device === \"vivo_x90\" ? \"vivo X90\" : \"iPad Air 6\";\n    tr.innerHTML = `<td><span class=\"tag ${r.device === 'vivo_x90' ? 'vivo' : 'ipad'}\">${dev}</span></td>\n      <td>${r.app_label}</td>\n      <td>${fmtClock(r.clip_start_ms)}</td>\n      <td>${fmtClock(r.clip_end_ms)}</td>\n      <td>${fmtDuration(r.clip_duration_ms)}${r.estimated ? '<span class=\"tag est\">估算</span>' : \"\"}</td>\n      <td>${r.source === \"time_pocket\" ? \"精确\" : (r.source === \"screen_time\" ? \"屏幕时间\" : \"快捷指令\")}</td>`;\n    tbody.appendChild(tr);\n  });\n}\n\n/* ---------- 分享图：Canvas 绘制后下载 ---------- */\nfunction roundRect(ctx, x, y, w, h, r) {\n  ctx.beginPath();\n  ctx.moveTo(x + r, y);\n  ctx.arcTo(x + w, y, x + w, y + h, r);\n  ctx.arcTo(x + w, y + h, x, y + h, r);\n  ctx.arcTo(x, y + h, x, y, r);\n  ctx.arcTo(x, y, x + w, y, r);\n  ctx.closePath();\n}\n\nasync function buildShareImage(days, rangeLabel) {\n  const mode = $(\"#f-mode\").value;\n  const device = $(\"#f-device\").value;\n  const end = todayStr();\n  const start = days === 1 ? end : (() => {\n    const d = new Date(Date.parse(end + \"T00:00:00+08:00\") - (days - 1) * 86400000);\n    return d.toISOString().slice(0, 10);\n  })();\n  const [summary, trendRows] = await Promise.all([\n    api(`/api/summary?date=${end}&device=${device}&mode=${mode}`),\n    api(`/api/trend?days=${days}&device=${device}&mode=${mode}`),\n  ]);\n\n  const W = 720, H = 900;\n  const cv = document.createElement(\"canvas\");\n  cv.width = W; cv.height = H;\n  const ctx = cv.getContext(\"2d\");\n  const dark = window.matchMedia && window.matchMedia(\"(prefers-color-scheme: dark)\").matches;\n  const bg = dark ? \"#0f172a\" : \"#f8fafc\";\n  const fg = dark ? \"#e2e8f0\" : \"#0f172a\";\n  const muted = dark ? \"#94a3b8\" : \"#64748b\";\n  const card = dark ? \"#1e293b\" : \"#ffffff\";\n  const line = dark ? \"#334155\" : \"#e2e8f0\";\n\n  ctx.fillStyle = bg;\n  ctx.fillRect(0, 0, W, H);\n\n  // 标题\n  ctx.fillStyle = fg;\n  ctx.font = \"600 30px system-ui, -apple-system, 'PingFang SC', sans-serif\";\n  ctx.fillText(\"应用使用时长\", 40, 62);\n  ctx.fillStyle = muted;\n  ctx.font = \"16px system-ui, -apple-system, 'PingFang SC', sans-serif\";\n  ctx.fillText(rangeLabel, 40, 92);\n\n  // 大数字\n  ctx.fillStyle = fg;\n  ctx.font = \"700 54px system-ui, -apple-system, 'PingFang SC', sans-serif\";\n  ctx.fillText(fmtDuration(summary.kpi.total_ms), 40, 168);\n  ctx.fillStyle = muted;\n  ctx.font = \"15px system-ui, -apple-system, 'PingFang SC', sans-serif\";\n  ctx.fillText(`共 ${summary.kpi.open_count} 次打开 · ${summary.kpi.app_count} 个 App`, 40, 198);\n\n  // 柱状趋势\n  const chartTop = 240, chartH = 200, chartW = W - 80;\n  const max = Math.max(...trendRows.map((r) => r.duration_ms), 1);\n  const bw = Math.min(38, (chartW / Math.max(trendRows.length, 1)) * 0.6);\n  const gap = (chartW - bw * trendRows.length) / Math.max(trendRows.length - 1, 1);\n  trendRows.forEach((r, i) => {\n    const h = Math.max((r.duration_ms / max) * chartH, r.duration_ms ? 3 : 0);\n    const x = 40 + i * (bw + gap);\n    const y = chartTop + chartH - h;\n    const grad = ctx.createLinearGradient(0, y, 0, y + h);\n    grad.addColorStop(0, dark ? \"#818cf8\" : \"#6366f1\");\n    grad.addColorStop(1, dark ? \"#4338ca\" : \"#a5b4fc\");\n    ctx.fillStyle = grad;\n    roundRect(ctx, x, y, bw, h, Math.min(6, bw / 3));\n    ctx.fill();\n    ctx.fillStyle = muted;\n    ctx.font = \"12px system-ui, sans-serif\";\n    ctx.textAlign = \"center\";\n    ctx.fillText(r.date.slice(5), x + bw / 2, chartTop + chartH + 20);\n    ctx.textAlign = \"left\";\n  });\n  ctx.strokeStyle = line;\n  ctx.beginPath();\n  ctx.moveTo(40, chartTop + chartH + 0.5);\n  ctx.lineTo(W - 40, chartTop + chartH + 0.5);\n  ctx.stroke();\n\n  // Top 应用\n  let y = chartTop + chartH + 60;\n  ctx.fillStyle = fg;\n  ctx.font = \"600 18px system-ui, -apple-system, 'PingFang SC', sans-serif\";\n  ctx.fillText(\"用时最多的应用\", 40, y);\n  y += 16;\n  const top = summary.apps.slice(0, 6);\n  const amax = Math.max(...top.map((a) => a.duration_ms), 1);\n  top.forEach((a, i) => {\n    y += 34;\n    ctx.fillStyle = fg;\n    ctx.font = \"15px system-ui, -apple-system, 'PingFang SC', sans-serif\";\n    ctx.fillText(`${i + 1}. ${a.label}`, 40, y);\n    ctx.fillStyle = muted;\n    ctx.textAlign = \"right\";\n    ctx.fillText(fmtDuration(a.duration_ms), W - 40, y);\n    ctx.textAlign = \"left\";\n    // 底部细条\n    ctx.fillStyle = dark ? \"#334155\" : \"#e2e8f0\";\n    roundRect(ctx, 40, y + 6, W - 80, 5, 2.5);\n    ctx.fill();\n    ctx.fillStyle = dark ? \"#818cf8\" : \"#6366f1\";\n    roundRect(ctx, 40, y + 6, Math.max((a.duration_ms / amax) * (W - 80), 4), 5, 2.5);\n    ctx.fill();\n  });\n\n  // 页脚\n  ctx.fillStyle = muted;\n  ctx.font = \"13px system-ui, -apple-system, 'PingFang SC', sans-serif\";\n  ctx.fillText(`${mode === \"union\" ? \"去重口径（真实占用时间）\" : \"相加口径（设备投入量）\"} · 来自 vivo X90 + iPad Air 6`, 40, H - 40);\n\n  return cv;\n}\n\nasync function shareImage(days) {\n  const rangeLabel = days === 1 ? todayStr() : `近 ${days} 天`;\n  const btn = days === 1 ? $(\"#btn-share\") : $(\"#btn-share-week\");\n  const old = btn.textContent;\n  btn.textContent = \"生成中...\";\n  try {\n    const cv = await buildShareImage(days, rangeLabel);\n    const blob = await new Promise((res) => cv.toBlob(res, \"image/png\"));\n    const url = URL.createObjectURL(blob);\n    const a = document.createElement(\"a\");\n    a.href = url;\n    a.download = `使用时长-${days === 1 ? todayStr() : \"近\" + days + \"天\"}.png`;\n    document.body.appendChild(a);\n    a.click();\n    a.remove();\n    setTimeout(() => URL.revokeObjectURL(url), 4000);\n  } catch (e) {\n    alert(\"生成分享图失败：\" + e.message);\n  } finally {\n    btn.textContent = old;\n  }\n}\n$(\"#btn-share\").addEventListener(\"click\", () => shareImage(1));\n$(\"#btn-share-week\").addEventListener(\"click\", () => shareImage(7));\n\n/* ---------- 导入 ---------- */\n$(\"#form-import\").addEventListener(\"submit\", async (e) => {\n  e.preventDefault();\n  const file = $(\"#import-file\").files[0];\n  if (!file) return;\n  const result = $(\"#import-result\");\n  result.textContent = \"读取并上传中...\";\n  try {\n    const text = await file.text();\n    const data = await api(\"/api/import/android\", {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: text,\n    });\n    result.innerHTML = `✅ 导入成功：新增 <strong>${data.imported}</strong> 条，跳过（重复/无效）<strong>${data.skipped}</strong> 条，共 ${data.total} 条。`;\n    loadDashboard();\n  } catch (err) {\n    result.textContent = \"❌ 导入失败：\" + err.message;\n  }\n});\n\n$(\"#btn-test-report\").addEventListener(\"click\", async () => {\n  const text = $(\"#test-report\").value.trim();\n  if (!text) return;\n  const apps = [];\n  for (const line of text.split(/\\r?\\n/)) {\n    const t = line.trim();\n    if (!t) continue;\n    // 真实格式：微信 (1 小时 45 分钟) —— 整段时长交给后端解析\n    const pm = t.match(/^(.+?)\\s*[\\(（]\\s*([^)）]+)\\s*[\\)）]\\s*$/);\n    if (pm) { apps.push({ label: pm[1].trim(), raw: pm[2].trim() }); continue; }\n    const parts = t.split(/[,，|\\t]/).map((x) => x.trim());\n    if (parts.length >= 2 && parts[0] && !isNaN(parseFloat(parts[1]))) {\n      apps.push({ label: parts[0], minutes: parseFloat(parts[1]) });\n    }\n  }\n  if (!apps.length) { $(\"#test-result\").textContent = \"❌ 格式错误：请每行填「应用名,分钟数」\"; return; }\n  try {\n    const data = await api(\"/api/ipad/daily\", { method: \"POST\", body: JSON.stringify({ apps }) });\n    $(\"#test-result\").textContent = `✅ 已上报 ${data.date}：${data.count} 个 App，共 ${Math.round(data.total_ms / 60000)} 分钟`;\n    loadDashboard();\n  } catch (err) {\n    $(\"#test-result\").textContent = \"❌ 上报失败：\" + err.message;\n  }\n});\n\n$(\"#btn-reset\").addEventListener(\"click\", async () => {\n  if (!confirm(\"确定清空云端全部数据？此操作不可恢复。\")) return;\n  await api(\"/api/reset\", { method: \"POST\" });\n  alert(\"已清空\");\n  loadDashboard();\n});\n\n/* ================= 数据管理页 ================= */\nlet syncToken = localStorage.getItem(\"time_token\") || \"\";\n$(\"#export-token\").value = syncToken;\n$(\"#push-token\").value = syncToken;\n[\"#export-token\", \"#push-token\"].forEach((sel) => {\n  $(sel).addEventListener(\"input\", (e) => {\n    syncToken = e.target.value.trim();\n    localStorage.setItem(\"time_token\", syncToken);\n    const other = sel === \"#export-token\" ? \"#push-token\" : \"#export-token\";\n    $(other).value = syncToken;\n  });\n});\n\nfunction tokenQuery() {\n  return syncToken ? \"?k=\" + encodeURIComponent(syncToken) : \"\";\n}\n\nasync function loadManage() {\n  const el = $(\"#manage-status\");\n  try {\n    const st = await api(\"/api/status\");\n    const fmt = (ms) => (ms ? new Date(ms).toLocaleString(\"zh-CN\") : \"无\");\n    const rows = (st.devices || []).map((d) => {\n      const name = d.device === \"vivo_x90\" ? \"vivo X90\" : \"iPad Air 6\";\n      return `<tr><td>${name}</td><td>${d.n} 条</td><td>${fmt(d.latest)}</td></tr>`;\n    }).join(\"\");\n    el.innerHTML = `\n      <table>\n        <thead><tr><th>设备</th><th>记录数</th><th>最新记录</th></tr></thead>\n        <tbody>${rows || '<tr><td colspan=\"3\" class=\"empty\">暂无数据</td></tr>'}</tbody>\n      </table>\n      <p class=\"desc\" style=\"margin-top:10px\">\n        共 <strong>${(st.stats && st.stats.total) || 0}</strong> 条记录 ·\n        最早 ${fmt(st.stats && st.stats.first_ms)} ·\n        最新 ${fmt(st.stats && st.stats.last_ms)}<br>\n        保留期 ${st.retention_days} 天 ·\n        推送渠道 ${st.push_configured ? \"已配置\" : \"未配置\"} ·\n        写入令牌 ${st.token_required ? \"已启用\" : \"未启用\"}\n      </p>`;\n  } catch (e) {\n    el.textContent = \"加载失败：\" + e.message;\n  }\n}\n\nfunction downloadExport(format) {\n  const url = `/api/export?format=${format}${syncToken ? (format ? \"&\" : \"?\") + \"k=\" + encodeURIComponent(syncToken) : \"\"}`;\n  window.open(url, \"_blank\");\n  $(\"#export-result\").textContent = `已请求下载 ${format.toUpperCase()} 文件。若浏览器弹出\"是否允许下载\"提示，请选择允许。`;\n}\n\n$(\"#btn-export-json\").addEventListener(\"click\", () => downloadExport(\"json\"));\n$(\"#btn-export-csv\").addEventListener(\"click\", () => downloadExport(\"csv\"));\n\n$(\"#btn-cleanup-dry\").addEventListener(\"click\", async () => {\n  const days = $(\"#cleanup-days\").value;\n  const el = $(\"#cleanup-result\");\n  el.textContent = \"试运行中...\";\n  try {\n    const r = await api(`/api/cleanup?keep_days=${days}&dry=1${syncToken ? \"&k=\" + encodeURIComponent(syncToken) : \"\"}`, { method: \"POST\" });\n    el.innerHTML = `试运行结果：将会删除 <strong>${r.would_delete}</strong> 条（保留最近 ${r.keep_days} 天）。未真正删除任何数据。`;\n  } catch (e) {\n    el.textContent = \"❌ \" + e.message;\n  }\n});\n\n$(\"#btn-cleanup\").addEventListener(\"click\", async () => {\n  const days = $(\"#cleanup-days\").value;\n  if (!confirm(`确定删除 ${days} 天之前的数据？此操作不可恢复，建议先导出备份。`)) return;\n  const el = $(\"#cleanup-result\");\n  el.textContent = \"清理中...\";\n  try {\n    const r = await api(`/api/cleanup?keep_days=${days}${syncToken ? \"&k=\" + encodeURIComponent(syncToken) : \"\"}`, { method: \"POST\" });\n    el.innerHTML = `✅ 已清理 <strong>${r.deleted}</strong> 条过期记录（保留最近 ${r.keep_days} 天）。`;\n    loadManage();\n    loadDashboard();\n  } catch (e) {\n    el.textContent = \"❌ \" + e.message;\n  }\n});\n\n$(\"#btn-push-test\").addEventListener(\"click\", async () => {\n  const el = $(\"#push-result\");\n  el.textContent = \"推送中...\";\n  try {\n    const date = (() => {\n      const d = new Date(Date.now() + 8 * 3600000 - 86400000);\n      return d.toISOString().slice(0, 10);\n    })();\n    const r = await api(`/api/push?date=${date}${syncToken ? \"&k=\" + encodeURIComponent(syncToken) : \"\"}`, { method: \"POST\" });\n    el.innerHTML = r.status === \"ok\"\n      ? `✅ 推送成功（${r.type}）。内容预览：<br><pre class=\"pre\">${escapeHtml(r.text)}</pre>`\n      : `⚠️ 推送未成功：${r.status}${r.reason ? \"（\" + r.reason + \"）\" : \"\"}${r.http ? \"（HTTP \" + r.http + \"）\" : \"\"}。请检查 PUSH_WEBHOOK 是否配置正确。`;\n  } catch (e) {\n    el.textContent = \"❌ \" + e.message;\n  }\n});\n\nfunction escapeHtml(s) {\n  return String(s).replace(/[&<>\"]/g, (c) => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\" }[c]));\n}\n\n$$(\".tab\").forEach((btn) => {\n  if (btn.dataset.page === \"manage\") {\n    btn.addEventListener(\"click\", () => setTimeout(loadManage, 0));\n  }\n});\n\n/* ================= 分析页 ================= */\n// 默认分类规则：{分类: [关键词...]}，按对象顺序匹配，命中即归类\nconst DEFAULT_RULES = {\n  \"学习\": [\"学习通\", \"知网\", \"超星\", \"雨课堂\", \"慕课\", \"mooc\", \"edx\", \"coursera\", \"anki\", \"墨墨\", \"不背单词\", \"考研\", \"题库\", \"作业帮\", \"学习\"],\n  \"工作\": [\"企业微信\", \"钉钉\", \"飞书\", \"邮件\", \"mail\", \"outlook\", \"腾讯会议\", \"zoom\", \"wps\", \"office\", \"文档\"],\n  \"影音娱乐\": [\"抖音\", \"快手\", \"哔哩\", \"b站\", \"bilibili\", \"腾讯视频\", \"爱奇艺\", \"优酷\", \"芒果\", \"netflix\", \"youtube\", \"音乐\", \"网易云\", \"qq音乐\", \"spotify\", \"播客\", \"小红书\"],\n  \"游戏\": [\"王者\", \"和平精英\", \"原神\", \"英雄联盟\", \"lol\", \"游戏\", \"game\", \"steam\", \"蛋仔\"],\n  \"社交资讯\": [\"微博\", \"知乎\", \"贴吧\", \"qq\", \"微信\", \"safari\", \"chrome\", \"浏览器\", \"新闻\", \"今日头条\", \"即刻\", \"豆瓣\"],\n};\nconst DEFAULT_GOALS = { \"学习\": 180, \"工作\": 120, \"影音娱乐\": 90, \"游戏\": 60, \"社交资讯\": 60 }; // 分钟/天\n\nfunction loadRules() {\n  try { return JSON.parse(localStorage.getItem(\"time_rules\")) || { ...DEFAULT_RULES }; }\n  catch (e) { return { ...DEFAULT_RULES }; }\n}\nfunction loadGoals() {\n  try { return JSON.parse(localStorage.getItem(\"time_goals\")) || { ...DEFAULT_GOALS }; }\n  catch (e) { return { ...DEFAULT_GOALS }; }\n}\nfunction classifyApp(label, key, rules) {\n  const s = (label + \" \" + key).toLowerCase();\n  for (const [cat, kws] of Object.entries(rules)) {\n    for (const kw of kws) {\n      if (s.includes(kw.toLowerCase())) return cat;\n    }\n  }\n  return \"其他\";\n}\n\n$(\"#btn-analysis-refresh\").addEventListener(\"click\", loadAnalysis);\n$(\"#a-range\").addEventListener(\"change\", loadAnalysis);\n$(\"#a-device\").addEventListener(\"change\", loadAnalysis);\n\nasync function loadAnalysis() {\n  const days = parseInt($(\"#a-range\").value, 10);\n  const device = $(\"#a-device\").value;\n  const mode = $(\"#f-mode\").value;\n  $(\"#analysis-note\").textContent = \"分析中...\";\n  try {\n    const [apps, trendRows] = await Promise.all([\n      api(`/api/apps_range?days=${days}&device=${device}&mode=${mode}`),\n      api(`/api/trend?days=${days * 2}&device=${device}&mode=${mode}`),\n    ]);\n    const rules = loadRules();\n    const goals = loadGoals();\n    renderCategory(apps, rules);\n    renderGoals(apps, rules, goals, days);\n    renderReport(apps, rules, days, device);\n    renderCompare(trendRows, days);\n    renderRulesEditor(rules);\n    $(\"#a-range-label\").textContent = \"近 \" + days + \" 天\";\n    $(\"#analysis-note\").textContent = \"已分析 · \" + new Date().toLocaleTimeString(\"zh-CN\");\n  } catch (e) {\n    $(\"#analysis-note\").textContent = \"分析失败：\" + e.message;\n  }\n}\n\nfunction aggregateByCategory(apps, rules) {\n  const m = {};\n  for (const a of apps) {\n    const cat = classifyApp(a.label, a.key, rules);\n    if (!m[cat]) m[cat] = { cat, duration_ms: 0, count: 0, apps: [] };\n    m[cat].duration_ms += a.duration_ms;\n    m[cat].count += a.count;\n    m[cat].apps.push(a);\n  }\n  return Object.values(m).sort((a, b) => b.duration_ms - a.duration_ms);\n}\n\nfunction renderCategory(apps, rules) {\n  const el = $(\"#chart-category\");\n  el.innerHTML = \"\";\n  const cats = aggregateByCategory(apps, rules);\n  if (!cats.length) { el.innerHTML = '<div class=\"empty\">暂无数据</div>'; return; }\n  const max = Math.max(...cats.map((c) => c.duration_ms), 1);\n  // 固定语义配色，避免同一分类每次换颜色\n  const CAT_COLORS = { \"学习\": \"#8b5cf6\", \"工作\": \"#2563eb\", \"影音娱乐\": \"#f59e0b\", \"游戏\": \"#ef4444\", \"社交资讯\": \"#06b6d4\", \"其他\": \"#94a3b8\" };\n  cats.forEach((c, i) => {\n    const row = document.createElement(\"div\");\n    row.className = \"app-row\";\n    const name = document.createElement(\"div\");\n    name.className = \"app-name\";\n    name.textContent = c.cat;\n    const wrap = document.createElement(\"div\");\n    wrap.className = \"app-bar-wrap\";\n    const bar = document.createElement(\"div\");\n    bar.className = \"app-bar\";\n    bar.style.width = Math.max((c.duration_ms / max) * 100, 2) + \"%\";\n    bar.style.background = CAT_COLORS[c.cat] || [\"#8b5cf6\", \"#2563eb\", \"#f59e0b\", \"#ef4444\", \"#06b6d4\", \"#94a3b8\"][i % 6];\n    bar.style.boxShadow = \"none\";\n    wrap.appendChild(bar);\n    const time = document.createElement(\"div\");\n    time.className = \"app-time\";\n    time.textContent = fmtDuration(c.duration_ms);\n    time.title = c.apps.map((a) => a.label).join(\"、\");\n    row.appendChild(name); row.appendChild(wrap); row.appendChild(time);\n    el.appendChild(row);\n  });\n}\n\nfunction renderGoals(apps, rules, goals, days) {\n  const el = $(\"#goals\");\n  el.innerHTML = \"\";\n  const cats = aggregateByCategory(apps, rules);\n  const byCat = {};\n  cats.forEach((c) => { byCat[c.cat] = c.duration_ms; });\n  const allCats = Array.from(new Set([...Object.keys(goals), ...cats.map((c) => c.cat)]));\n  if (!allCats.length) { el.innerHTML = '<div class=\"empty\">暂无数据</div>'; return; }\n  allCats.forEach((cat) => {\n    const goalMin = goals[cat] || 0;\n    const usedMs = byCat[cat] || 0;\n    const dailyUsed = usedMs / 60000 / days; // 日均分钟\n    const pct = goalMin > 0 ? (dailyUsed / goalMin) * 100 : 0;\n    const row = document.createElement(\"div\");\n    row.className = \"goal-row\";\n    const name = document.createElement(\"div\");\n    name.className = \"goal-name\";\n    name.textContent = cat;\n    const track = document.createElement(\"div\");\n    track.className = \"goal-track\";\n    const fill = document.createElement(\"div\");\n    const cls = goalMin <= 0 ? \"none\" : pct > 100 ? \"over\" : \"ok\";\n    fill.className = \"goal-fill \" + cls;\n    fill.style.width = Math.min(pct, 100) + \"%\";\n    const txt = document.createElement(\"div\");\n    txt.className = \"goal-text\";\n    txt.textContent = goalMin > 0\n      ? `日均 ${Math.round(dailyUsed)} / ${goalMin} 分（${Math.round(pct)}%）`\n      : `日均 ${Math.round(dailyUsed)} 分`;\n    track.appendChild(fill); track.appendChild(txt);\n    const input = document.createElement(\"input\");\n    input.className = \"goal-input\";\n    input.type = \"number\";\n    input.min = \"0\";\n    input.value = goalMin;\n    input.title = \"每日目标（分钟），0 表示不设目标\";\n    input.addEventListener(\"change\", () => {\n      const g = loadGoals();\n      g[cat] = Math.max(0, parseInt(input.value, 10) || 0);\n      localStorage.setItem(\"time_goals\", JSON.stringify(g));\n      loadAnalysis();\n    });\n    const unit = document.createElement(\"span\");\n    unit.className = \"goal-unit\";\n    unit.textContent = \"分/天\";\n    row.appendChild(name); row.appendChild(track); row.appendChild(input); row.appendChild(unit);\n    el.appendChild(row);\n  });\n}\n\nfunction renderReport(apps, rules, days, device) {\n  const el = $(\"#report\");\n  const cats = aggregateByCategory(apps, rules);\n  if (!cats.length) { el.innerHTML = '<div class=\"empty\">暂无数据，导入后生成周报</div>'; return; }\n  const totalMs = cats.reduce((a, c) => a + c.duration_ms, 0);\n  const dailyMin = Math.round(totalMs / 60000 / days);\n  const topCat = cats[0];\n  const topShare = Math.round((topCat.duration_ms / totalMs) * 100);\n  const topApp = apps[0];\n  const devName = device === \"all\" ? \"两台设备\" : (device === \"vivo_x90\" ? \"vivo X90\" : \"iPad Air 6\");\n  const goalHit = (() => {\n    const goals = loadGoals();\n    const byCat = {};\n    cats.forEach((c) => { byCat[c.cat] = c.duration_ms; });\n    let hit = 0, set = 0;\n    for (const [cat, g] of Object.entries(goals)) {\n      if (g > 0) { set++; if (byCat[cat] / 60000 / days <= g) hit++; }\n    }\n    return set ? `${hit}/${set}` : null;\n  })();\n\n  el.innerHTML = `\n    <div class=\"sec\">近 <span class=\"hl\">${days}</span> 天你在 ${devName} 上共投入 <span class=\"hl\">${fmtDuration(totalMs)}</span>，平均每天约 <span class=\"hl\">${fmtDuration(dailyMin * 60000)}</span>。</div>\n    <div class=\"sec\">用时最多的是 <span class=\"hl\">${topCat.cat}</span>，占 <span class=\"hl\">${topShare}%</span>；单项 App 中 <span class=\"hl\">${topApp.label}</span> 居首（${fmtDuration(topApp.duration_ms)}）。</div>\n    <div class=\"sec\">分类明细：<ul>${cats.map((c) => `<li>${c.cat}：${fmtDuration(c.duration_ms)}，${c.count} 次</li>`).join(\"\")}</ul></div>\n    ${goalHit ? `<div class=\"sec\">每日目标达成情况：<span class=\"hl\">${goalHit}</span> 个分类控制在目标内。</div>` : \"\"}\n    <div class=\"sec\" style=\"color:var(--muted);font-size:12px\">注：vivo 时长与次数均为精确值；iPad 默认取系统「屏幕时间」的每日精确时长（无单次时刻/次数）。</div>`;\n}\n\nfunction renderCompare(trendRows, days) {\n  const el = $(\"#chart-compare\");\n  el.innerHTML = \"\";\n  if (!trendRows.length) { el.innerHTML = '<div class=\"empty\">暂无数据</div>'; return; }\n  const prev = trendRows.slice(0, days);\n  const curr = trendRows.slice(days);\n  const prevTotal = prev.reduce((a, r) => a + r.duration_ms, 0);\n  const currTotal = curr.reduce((a, r) => a + r.duration_ms, 0);\n  const max = Math.max(prevTotal, currTotal, 1);\n  const groups = [\n    { label: \"上一周期\", value: prevTotal },\n    { label: \"本周期\", value: currTotal },\n  ];\n  groups.forEach((g, i) => {\n    const col = document.createElement(\"div\");\n    col.className = \"trend-col\";\n    const stack = document.createElement(\"div\");\n    stack.className = \"trend-stack\";\n    const seg = document.createElement(\"div\");\n    seg.className = \"trend-seg \" + (i === 1 ? \"vivo\" : \"ipad\");\n    seg.style.height = \"100%\";\n    stack.style.height = Math.max((g.value / max) * 170, 3) + \"px\";\n    stack.appendChild(seg);\n    const tip = document.createElement(\"div\");\n    tip.className = \"trend-tip\";\n    tip.textContent = `${g.label}：${fmtDuration(g.value)}`;\n    const label = document.createElement(\"div\");\n    label.className = \"trend-label\";\n    label.textContent = g.label;\n    col.appendChild(tip); col.appendChild(stack); col.appendChild(label);\n    el.appendChild(col);\n  });\n  const delta = prevTotal > 0 ? Math.round(((currTotal - prevTotal) / prevTotal) * 100) : null;\n  const note = document.createElement(\"div\");\n  note.className = \"hint\";\n  note.style.marginLeft = \"20px\";\n  note.textContent = delta === null ? \"上一周期无数据\" : `本周期${delta >= 0 ? \"增加\" : \"减少\"} ${Math.abs(delta)}%`;\n  el.appendChild(note);\n}\n\nfunction renderRulesEditor(rules) {\n  $(\"#rules-editor\").value = Object.entries(rules).map(([cat, kws]) => `${cat}: ${kws.join(\", \")}`).join(\"\\n\");\n}\nfunction parseRules(text) {\n  const rules = {};\n  for (const line of text.split(\"\\n\")) {\n    const idx = line.indexOf(\":\");\n    if (idx < 0) continue;\n    const cat = line.slice(0, idx).trim();\n    const kws = line.slice(idx + 1).split(/[,，]/).map((s) => s.trim()).filter(Boolean);\n    if (cat && kws.length) rules[cat] = kws;\n  }\n  return rules;\n}\n$(\"#btn-save-rules\").addEventListener(\"click\", () => {\n  const rules = parseRules($(\"#rules-editor\").value);\n  if (!Object.keys(rules).length) { $(\"#rules-result\").textContent = \"❌ 规则不能为空\"; return; }\n  localStorage.setItem(\"time_rules\", JSON.stringify(rules));\n  $(\"#rules-result\").textContent = \"✅ 已保存分类规则\";\n  loadAnalysis();\n});\n$(\"#btn-reset-rules\").addEventListener(\"click\", () => {\n  localStorage.setItem(\"time_rules\", JSON.stringify(DEFAULT_RULES));\n  $(\"#rules-result\").textContent = \"✅ 已恢复默认规则\";\n  loadAnalysis();\n});\n\n// 切到分析页时加载一次\n$$(\".tab\").forEach((btn) => {\n  if (btn.dataset.page === \"analysis\") {\n    btn.addEventListener(\"click\", () => setTimeout(loadAnalysis, 0));\n  }\n});\n\n/* ---------- PWA：注册 Service Worker，可添加到主屏幕、离线查看 ---------- */\nif (\"serviceWorker\" in navigator) {\n  window.addEventListener(\"load\", () => {\n    navigator.serviceWorker.register(\"/sw.js\").catch(() => { /* 注册失败不影响使用 */ });\n  });\n}\n\nloadDashboard();\n\n</script>\n</body>\n</html>\n";

