const SW = `/* 应用时间看板 · 离线缓存 */
const CACHE = 'app-time-v3';
const SHELL = ['/', '/manifest.webmanifest', '/icon-192.png'];

self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(SHELL)).catch(() => {}));
  self.skipWaiting();
});

self.addEventListener('activate', (e) => {
  e.waitUntil(
    caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
  );
  self.clients.claim();
});

self.addEventListener('fetch', (e) => {
  const url = new URL(e.request.url);
  if (e.request.method !== 'GET' || url.pathname.startsWith('/api/')) return;
  // 页面导航：网络优先，断网时回落到缓存
  if (e.request.mode === 'navigate') {
    e.respondWith(
      fetch(e.request).then((res) => {
        const copy = res.clone();
        caches.open(CACHE).then((c) => c.put('/', copy)).catch(() => {});
        return res;
      }).catch(() => caches.match('/'))
    );
    return;
  }
  // 静态资源：缓存优先
  e.respondWith(
    caches.match(e.request).then((hit) => hit || fetch(e.request).then((res) => {
      if (res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(e.request, copy)).catch(() => {}); }
      return res;
    }))
  );
});
`;

/* 图标：构建时由 build.py 注入 base64 */
const ICONS = {"apple-touch-icon.png": "", "icon-192.png": "", "icon-512.png": "", "icon-maskable-512.png": ""};

/* Android 自动同步版 APK：构建时由 build.py 注入 base64，提供网页下载 */
const APK_B64 = "";


const DEVICES = {
  vivo_x90: "vivo X90（Android）",
  ipad_air6: "iPad Air 6（iOS）",
};

const TZ = 8 * 3600 * 1000;
const GAP_THRESHOLD = 30 * 60 * 1000;      // 两次打开间隔超过 30 分钟，判定中间锁屏/离开
const DEFAULT_REASONABLE = 15 * 60 * 1000; // 无历史数据时，单次会话默认按 15 分钟计
const MIN_SESSION_MS = 10 * 1000;          // 短于 10 秒的片段视为误触，默认不计入统计
const DEFAULT_RETENTION_DAYS = 540;        // 默认保留 540 天（约 1.5 年），超出可清理

/* ---------------- 时间工具 ---------------- */
function dayStart(dateStr) {
  // dateStr: YYYY-MM-DD（北京时间）
  return Date.parse(dateStr + "T00:00:00+08:00");
}
function localDateKey(ms) {
  return new Date(ms + TZ).toISOString().slice(0, 10);
}
function localHour(ms) {
  return new Date(ms + TZ).getUTCHours();
}
function effDur(r, now, avgMs) {
  // 会话有效时长：已结束用存储值；未结束按当前时间估算并封顶
  if (r.duration_ms !== null && r.duration_ms !== undefined) return r.duration_ms;
  if (r.end_ms !== null && r.end_ms !== undefined) return r.end_ms - r.start_ms;
  // 未结束会话：按当前时间估算
  const gap = Math.max(now - r.start_ms, 0);
  return estimateByGap(gap, avgMs);
}

// 异常间隔检测：间隔在阈值内按实际计；超过阈值说明中间锁屏/离开，用历史平均封顶
function estimateByGap(gapMs, avgMs) {
  if (gapMs <= GAP_THRESHOLD) return gapMs;
  // 有历史平均：用 1.5 倍平均作为合理上限；无历史：默认 15 分钟
  const cap = (typeof avgMs === "number" && avgMs > 0) ? avgMs * 1.5 : DEFAULT_REASONABLE;
  return Math.min(gapMs, Math.max(cap, 60000)); // 至少 1 分钟
}
function clampDays(v) {
  const n = parseInt(v, 10);
  if (!n || n < 1) return 7;
  return Math.min(n, 30);
}

/* ---------------- 统计口径：相加 vs 去重并集 ----------------
 * 相加（sum）：两台设备各自时长直接相加，代表"设备投入量"。
 * 去重（union）：同一时刻两台设备都在用，只算一次，代表"真实占用时间"。
 * 注意：iPad 屏幕时间日报只有当日总量、没有分布时刻，无法参与区间去重，
 * 这部分在 union 口径下按原值计入（kpi.daily_ms），并在前端标注。
 */

/** 取一条记录的占用区间 [开始, 结束)；未结束的按估算时长封顶。 */
function sessionInterval(r, now, avgMs) {
  const start = Number(r.start_ms);
  if (!Number.isFinite(start)) return null;
  if (r.end_ms !== null && r.end_ms !== undefined) {
    const end = Number(r.end_ms);
    if (!Number.isFinite(end) || end <= start) return null;
    return [start, end];
  }
  const dur = estimateByGap(Math.max(now - start, 0), avgMs);
  return [start, start + dur];
}

/** 计算一组区间的并集长度（重叠部分只算一次）。 */
function unionLength(intervals) {
  if (!intervals || !intervals.length) return 0;
  const arr = intervals.slice().sort((a, b) => a[0] - b[0]);
  let total = 0;
  let curStart = arr[0][0];
  let curEnd = arr[0][1];
  for (let i = 1; i < arr.length; i++) {
    const [s, e] = arr[i];
    if (s <= curEnd) {
      if (e > curEnd) curEnd = e;
    } else {
      total += curEnd - curStart;
      curStart = s;
      curEnd = e;
    }
  }
  return total + (curEnd - curStart);
}

/** 解析口径参数：默认相加。 */
function parseMode(v) {
  return String(v || "").toLowerCase() === "union" ? "union" : "sum";
}

/** 解析短会话过滤阈值（毫秒）：默认 10 秒，0 表示不过滤。 */
function parseMinMs(v) {
  if (v === null || v === undefined || v === "") return MIN_SESSION_MS;
  const n = parseInt(v, 10);
  if (!Number.isFinite(n) || n < 0) return MIN_SESSION_MS;
  return n;
}

/* ---------------- D1 查询 ---------------- */
async function querySessions(env, { date, device, days, now, minMs }) {
  let sql = "SELECT * FROM sessions WHERE 1=1";
  const args = [];
  if (date) {
    const s = dayStart(date);
    sql += " AND start_ms >= ? AND start_ms < ?";
    args.push(s, s + 86400000);
  } else if (days) {
    sql += " AND start_ms >= ?";
    args.push(now - days * 86400000);
  }
  if (device && device !== "all") {
    sql += " AND device = ?";
    args.push(device);
  }
  sql += " ORDER BY start_ms DESC LIMIT 10000";
  const res = await env.DB.prepare(sql).bind(...args).all();
  let list = res.results;

  // 过滤误触的极短片段（默认 10 秒以下不计）；日报记录时长较大，不受影响
  const floor = minMs === undefined ? MIN_SESSION_MS : minMs;
  if (floor > 0) {
    list = list.filter((r) => {
      if (isDailyTotal(r)) return true;
      const dur = effDur(r, now, r._avg);
      return dur >= floor;
    });
  }

  // 为需要估算的 iPad 会话附加该 App 的历史平均时长（一次批量查询，避免逐行查库）
  const needAvg = new Set();
  for (const r of list) {
    if (r.device === "ipad_air6" && (r.end_ms === null || r.end_ms === undefined || r.estimated)) {
      needAvg.add(r.app_key);
    }
  }
  if (needAvg.size) {
    const avgs = {};
    for (const key of needAvg) {
      const h = await env.DB.prepare(
        "SELECT AVG(duration_ms) AS avg FROM sessions WHERE device=? AND app_key=? AND duration_ms>=60000 AND duration_ms<=?"
      ).bind("ipad_air6", key, GAP_THRESHOLD).first();
      avgs[key] = h && h.avg ? h.avg : null;
    }
    for (const r of list) {
      if (needAvg.has(r.app_key)) r._avg = avgs[r.app_key];
    }
  }
  return list;
}

/* ---------------- iPad 上报（估算时长） ---------------- */
async function addIpadEvent(env, appLabel, atMs) {
  const now = Date.now();
  const at = atMs ? Number(atMs) : now;
  const key = String(appLabel || "").trim();
  if (!key) throw new Error("app 不能为空");

  const dup = await env.DB.prepare(
    "SELECT id FROM sessions WHERE device=? AND app_label=? AND start_ms>? AND start_ms<? LIMIT 1"
  ).bind("ipad_air6", key, at - 30000, at + 30000).first();
  if (dup) return { status: "duplicate", app: key, at };

  const prev = await env.DB.prepare(
    "SELECT * FROM sessions WHERE device=? AND end_ms IS NULL ORDER BY start_ms DESC LIMIT 1"
  ).bind("ipad_air6").first();

  const stmts = [];
  if (prev && at > prev.start_ms) {
    // 查询该 App 历史已完成会话的平均时长（只取 1~ GAP_THRESHOLD 的合理值，避免被旧的高估数据污染）
    const hist = await env.DB.prepare(
      "SELECT AVG(duration_ms) AS avg FROM sessions WHERE device=? AND app_key=? AND duration_ms>=60000 AND duration_ms<=? AND id<>?"
    ).bind("ipad_air6", prev.app_key, GAP_THRESHOLD, prev.id).first();
    const avgMs = hist && hist.avg ? hist.avg : null;
    const gap = at - prev.start_ms;
    const dur = estimateByGap(gap, avgMs);
    // end_ms 用「开始 + 有效时长」而非真实打开时刻，让时间线也反映截断后的合理时长
    stmts.push(env.DB.prepare(
      "UPDATE sessions SET end_ms=?, duration_ms=?, estimated=1 WHERE id=?"
    ).bind(prev.start_ms + dur, dur, prev.id));
  }
  stmts.push(env.DB.prepare(
    "INSERT OR IGNORE INTO sessions (device,app_key,app_label,start_ms,end_ms,duration_ms,source,estimated,created_at) VALUES (?,?,?,?,?,?,?,?,?)"
  ).bind("ipad_air6", key, key, at, null, null, "ipad_shortcut", 0, now));
  await env.DB.batch(stmts);
  return { status: "ok", app: key, at };
}

/* ---------------- iPad 屏幕时间日报（iOS 26「获取 App 与网站活动」，系统精确时长） ---------------- */
function isDailyTotal(r) {
  return !!(r && r.source === "screen_time");
}

function pickField(obj, names) {
  for (const n of names) {
    if (obj[n] !== undefined && obj[n] !== null) return obj[n];
  }
  return null;
}

// 把时长解析成毫秒：支持数字（>10万当毫秒，否则当分钟）、"1小时23分钟"、"45分钟"、"35min"、"30秒"
function parseDurationMs(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === "number" && isFinite(v)) {
    // 日报单个 App 合理范围 0~1440 分钟：≤1440 当分钟；>86400 当毫秒；其余当秒
    if (v > 86400000) return Math.round(v);
    if (v > 1440) return Math.round(v * 1000);
    return Math.round(v * 60000);
  }
  const s = String(v).trim();
  if (!s) return null;
  let total = 0, matched = false;
  const re = /(\d+(?:\.\d+)?)\s*(小时|分钟|分|秒|h|hr|hrs|min|mins|m|s|sec|secs)/gi;
  let m;
  while ((m = re.exec(s)) !== null) {
    const n = parseFloat(m[1]);
    const u = m[2].toLowerCase();
    if (u === "小时" || u === "h" || u === "hr" || u === "hrs") total += n * 3600000;
    else if (u === "秒" || u === "s" || u === "sec" || u === "secs") total += n * 1000;
    else total += n * 60000;
    matched = true;
  }
  if (matched) return Math.round(total);
  const n = parseFloat(s.replace(/[^\d.]/g, ""));
  return isNaN(n) ? null : Math.round(n * 60000);
}

// 宽容解析日报：JSON（各种常见字段名）或 "应用名|时长" 多行文本
function parseIpadDaily(raw, now) {
  const text = String(raw === undefined || raw === null ? "" : raw).trim();
  let date = null;
  let items = [];
  let parsed = null;
  try { parsed = JSON.parse(text); } catch (e) { /* 文本格式 */ }

  if (parsed && typeof parsed === "object") {
    date = pickField(parsed, ["date", "day", "dateKey", "日期"]);
    const field = pickField(parsed, ["apps", "data", "items", "activities", "appActivity", "result", "results", "应用列表", "应用"]);
    items = Array.isArray(field) ? field : (field && typeof field === "object"
      ? Object.keys(field).map((k) => {
          const v = field[k];
          return (v && typeof v === "object") ? Object.assign({ label: k }, v) : { label: k, minutes: v };
        })
      : []);
  } else if (text) {
    for (const line of text.split(/\r?\n/)) {
      let t = line.trim();
      if (!t) continue;
      const dm = t.match(/^(\d{4}-\d{2}-\d{2})\s*[|:,\t]\s*(.*)$/);
      if (dm && !date) {
        date = dm[1];
        t = dm[2]; // 日期后面若还有内容，继续当作数据处理
        if (!t) continue;
      }
      // iOS 26「获取 App 与网站活动」真实显示格式：微信 (1 小时 45 分钟)
      const pm = t.match(/^(.+?)\s*[\(（]\s*([^)）]+)\s*[\)）]\s*$/);
      if (pm) { items.push({ label: pm[1].trim(), raw: pm[2].trim() }); continue; }
      const parts = t.split(/[|,\t]/);
      if (parts.length >= 2) items.push({ label: parts[0], minutes: parts[1] });
    }
  }

  if (typeof date === "number") date = localDateKey(date);
  if (typeof date === "string") {
    date = date.trim().slice(0, 10).replace(/\//g, "-");
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) date = null;
  }
  if (!date) date = localDateKey(now - 86400000); // 默认昨天

  const apps = [];
  for (const it of items) {
    const obj = (typeof it === "string") ? { label: it } : it;
    if (!obj || typeof obj !== "object") continue;
    const label = pickField(obj, ["label", "name", "appName", "app_label", "app", "title", "application", "应用名称", "应用"]);
    if (!label) continue;
    let ms = pickField(obj, ["duration_ms", "durationMs", "milliseconds", "ms"]);
    if (ms === null) {
      const sec = pickField(obj, ["seconds", "sec", "durationSeconds", "duration_seconds"]);
      if (sec !== null) ms = (typeof sec === "number" && isFinite(sec)) ? Math.round(sec * 1000) : parseDurationMs(sec);
    }
    if (ms === null) ms = parseDurationMs(pickField(obj, ["minutes", "min", "mins", "totalMinutes", "usage", "duration", "时长", "使用时间", "使用时长"]));
    if (ms === null) ms = parseDurationMs(obj.raw);
    if (ms === null) continue;
    ms = Math.round(Number(ms));
    if (!(ms > 0)) continue;
    apps.push({ key: String(label).trim(), label: String(label).trim(), duration_ms: ms });
  }
  // 同名 App 合并
  const merged = {};
  for (const a of apps) {
    if (!merged[a.key]) merged[a.key] = a;
    else merged[a.key].duration_ms += a.duration_ms;
  }
  return { date, apps: Object.values(merged) };
}

async function addIpadDaily(env, raw) {
  const now = Date.now();
  const { date, apps } = parseIpadDaily(raw, now);
  if (!apps.length) throw new Error("未解析到任何 App 时长，请检查上报内容格式");
  const start = dayStart(date);
  const stmts = [];
  // 覆盖式：先清掉该日 iPad 旧记录（含旧版打开上报），避免重复
  stmts.push(env.DB.prepare(
    "DELETE FROM sessions WHERE device=? AND start_ms>=? AND start_ms<?"
  ).bind("ipad_air6", start, start + 86400000));
  for (const a of apps) {
    stmts.push(env.DB.prepare(
      "INSERT OR REPLACE INTO sessions (device,app_key,app_label,start_ms,end_ms,duration_ms,source,estimated,created_at) VALUES (?,?,?,?,?,?,?,?,?)"
    ).bind("ipad_air6", a.key, a.label, start, start + 86400000 - 1, a.duration_ms, "screen_time", 0, now));
  }
  for (let i = 0; i < stmts.length; i += 100) await env.DB.batch(stmts.slice(i, i + 100));
  return { status: "ok", date, count: apps.length, total_ms: apps.reduce((s, a) => s + a.duration_ms, 0) };
}

/* ---------------- Android 备份导入 ---------------- */
async function importTimepocket(env, data) {
  if (!data || data.format !== "time-pocket") throw new Error("不是 time-pocket 备份文件");
  const apps = {};
  for (const a of (data.apps || [])) apps[a.pkg] = a.label || a.pkg;
  const sessions = data.sessions || [];
  const stmts = [];
  let invalid = 0;
  for (const s of sessions) {
    const start = Number(s.start);
    const end = Number(s.end);
    if (!(end > start)) { invalid++; continue; }
    stmts.push(env.DB.prepare(
      "INSERT OR IGNORE INTO sessions (device,app_key,app_label,start_ms,end_ms,duration_ms,source,estimated,created_at) VALUES (?,?,?,?,?,?,?,?,?)"
    ).bind("vivo_x90", s.pkg, apps[s.pkg] || s.pkg, start, end, end - start, "time_pocket", 0, Date.now()));
  }
  let ok = 0;
  for (let i = 0; i < stmts.length; i += 100) {
    const results = await env.DB.batch(stmts.slice(i, i + 100));
    for (const r of results) if (r && r.success) ok++;
  }
  return { imported: ok, skipped: sessions.length - ok, total: sessions.length };
}

/* ---------------- 聚合纯函数（可测试） ---------------- */
function summary(rows, date, device, now, mode) {
  const useUnion = mode === "union";
  const apps = {};
  let count = 0, ipadMs = 0, vivoMs = 0, dailyMs = 0, sumTotal = 0;
  const allIntervals = [];
  const devIntervals = { ipad_air6: [], vivo_x90: [] };

  for (const r of rows) {
    const dur = effDur(r, now, r._avg);
    sumTotal += dur;
    // 两种口径都按"应用名"归并：安卓的包名（com.tencent.mm）与 iPad 的名称（微信）
    // 必须合成同一个 App，否则同一个应用会在排行里裂成两行
    const groupKey = (r.app_label || r.app_key || "").trim() || r.app_key;
    if (!apps[groupKey]) {
      apps[groupKey] = {
        key: r.app_key, label: r.app_label, device: r.device,
        duration_ms: 0, count: 0, estimated_count: 0,
        _intervals: [], _devices: new Set(),
      };
    }
    const a = apps[groupKey];
    a._devices.add(r.device);
    if (useUnion) {
      const iv = sessionInterval(r, now, r._avg);
      if (iv) {
        a._intervals.push(iv);
        allIntervals.push(iv);
        if (devIntervals[r.device]) devIntervals[r.device].push(iv);
      }
      if (isDailyTotal(r)) dailyMs += dur;
    } else {
      a.duration_ms += dur;
    }
    if (r.device === "ipad_air6") ipadMs += dur;
    if (r.device === "vivo_x90") vivoMs += dur;
    if (isDailyTotal(r)) continue; // 屏幕时间日报无"单次打开"概念，不计次数
    a.count += 1;
    if (r.estimated || r.end_ms === null || r.end_ms === undefined) a.estimated_count += 1;
    count += 1;
  }

  let total = sumTotal;
  if (useUnion) {
    for (const k of Object.keys(apps)) {
      const a = apps[k];
      if (a._intervals.length) a.duration_ms = unionLength(a._intervals);
      if (a._devices.size > 1) a.device = "both";
      delete a._intervals;
      delete a._devices;
    }
    // 总时长 = 全部区间的并集 + 日报总量（日报无分布时刻，无法参与去重）
    total = unionLength(allIntervals) + dailyMs;
    // 分设备时长也按各自并集计算，避免"两台设备同时用"被算成两倍
    ipadMs = unionLength(devIntervals.ipad_air6) + dailyMs;
    vivoMs = unionLength(devIntervals.vivo_x90);
  } else {
    for (const k of Object.keys(apps)) {
      const a = apps[k];
      if (a._devices.size > 1) a.device = "both";
      delete a._intervals;
      delete a._devices;
    }
  }

  const ranked = Object.values(apps).sort((a, b) => b.duration_ms - a.duration_ms);
  return {
    date,
    mode: useUnion ? "union" : "sum",
    kpi: {
      total_ms: total, sum_ms: sumTotal, open_count: count, app_count: ranked.length,
      ipad_ms: ipadMs, vivo_ms: vivoMs, daily_ms: dailyMs,
    },
    apps: ranked,
  };
}

function trend(rows, days, now, mode) {
  const useUnion = mode === "union";
  const buckets = {};
  for (let i = 0; i < days; i++) {
    const d = localDateKey(now - (days - 1 - i) * 86400000);
    buckets[d] = { date: d, duration_ms: 0, sum_ms: 0, count: 0, by_device: {}, _iv: {}, _dev: {} };
  }
  for (const r of rows) {
    const d = localDateKey(r.start_ms);
    if (!buckets[d]) continue;
    const dur = effDur(r, now, r._avg);
    const b = buckets[d];
    b.sum_ms += dur;
    const dv = b.by_device[r.device] || (b.by_device[r.device] = { duration_ms: 0, count: 0 });
    dv.duration_ms += dur;
    if (useUnion) {
      const iv = sessionInterval(r, now, r._avg);
      if (iv) {
        (b._iv[r.device] || (b._iv[r.device] = [])).push(iv);
      }
    }
    if (isDailyTotal(r)) continue; // 日报不计打开次数
    b.count += 1;
    dv.count += 1;
  }
  if (useUnion) {
    for (const d of Object.keys(buckets)) {
      const b = buckets[d];
      const ivs = [];
      for (const dev of Object.keys(b._iv)) ivs.push(...b._iv[dev]);
      b.duration_ms = unionLength(ivs);
      for (const dev of Object.keys(b.by_device)) {
        b.by_device[dev].duration_ms = unionLength(b._iv[dev] || []);
      }
      delete b._iv;
    }
  } else {
    for (const d of Object.keys(buckets)) buckets[d].duration_ms = buckets[d].sum_ms;
  }
  return Object.keys(buckets).sort().map((d) => buckets[d]);
}

// 区间内按 App 聚合（用于分析页分类）
function appsRange(rows, now, mode) {
  const useUnion = mode === "union";
  const apps = {};
  for (const r of rows) {
    // 按应用名归并，与 summary 保持一致
    const groupKey = (r.app_label || r.app_key || "").trim() || r.app_key;
    if (!apps[groupKey]) {
      apps[groupKey] = { key: r.app_key, label: r.app_label, device: r.device, duration_ms: 0, count: 0, _iv: [] };
    }
    const a = apps[groupKey];
    if (useUnion) {
      const iv = sessionInterval(r, now, r._avg);
      if (iv) a._iv.push(iv);
    } else {
      a.duration_ms += effDur(r, now, r._avg);
    }
    if (!isDailyTotal(r)) a.count += 1;
  }
  for (const k of Object.keys(apps)) {
    if (useUnion && apps[k]._iv.length) apps[k].duration_ms = unionLength(apps[k]._iv);
    delete apps[k]._iv;
  }
  return Object.values(apps).sort((a, b) => b.duration_ms - a.duration_ms);
}

function heatmap(rows, now) {
  const hours = Array.from({ length: 24 }, (_, h) => ({ hour: h, duration_ms: 0, count: 0 }));
  for (const r of rows) {
    if (isDailyTotal(r)) continue; // 日报没有时刻信息，不进热力图
    const h = localHour(r.start_ms);
    hours[h].duration_ms += effDur(r, now, r._avg);
    hours[h].count += 1;
  }
  return hours;
}

function timeline(rows, date, now) {
  const s = dayStart(date);
  const e = s + 86400000;
  const out = [];
  for (const r of rows) {
    if (isDailyTotal(r)) continue; // 日报没有时刻信息，不进时间线
    const cs = Math.max(r.start_ms, s);
    const rawEnd = (r.end_ms !== null && r.end_ms !== undefined)
      ? r.end_ms
      : Math.min(now, r.start_ms + (r._avg ? r._avg * 1.5 : DEFAULT_REASONABLE));
    const ce = Math.min(rawEnd, e);
    if (ce <= cs) continue;
    const o = Object.assign({}, r, { clip_start_ms: cs, clip_end_ms: ce, clip_duration_ms: ce - cs });
    if (r.end_ms === null || r.end_ms === undefined) o.estimated = 1;
    out.push(o);
  }
  out.sort((a, b) => a.clip_start_ms - b.clip_start_ms);
  return out;
}

/* ---------------- 节假日与工作日 ----------------
 * 2026 年中国大陆法定节假日安排（国务院办公厅 国办发明电〔2025〕7 号）。
 * 用于在看板上区分"工作日 / 休息日 / 调休上班日"，方便对比效率。
 */
const HOLIDAY_2026 = {
  // 放假日（闭区间）
  holidays: [
    ["2026-01-01", "2026-01-03"], // 元旦
    ["2026-02-15", "2026-02-23"], // 春节
    ["2026-04-04", "2026-04-06"], // 清明
    ["2026-05-01", "2026-05-05"], // 劳动节
    ["2026-06-19", "2026-06-21"], // 端午
    ["2026-09-25", "2026-09-27"], // 中秋
    ["2026-10-01", "2026-10-07"], // 国庆
  ],
  // 调休上班日（周末但要上班）
  workdays: [
    "2026-01-04", "2026-02-14", "2026-02-28",
    "2026-05-09", "2026-09-20", "2026-10-10",
  ],
};

const HOLIDAY_NAMES = {
  "2026-01-01": "元旦", "2026-02-17": "春节", "2026-04-05": "清明",
  "2026-05-01": "劳动节", "2026-06-19": "端午", "2026-09-25": "中秋",
  "2026-10-01": "国庆",
};

/** 判断某天是工作日 / 休息日 / 法定假日 / 调休上班日。 */
function dayType(dateStr) {
  const inHoliday = HOLIDAY_2026.holidays.some(([a, b]) => dateStr >= a && dateStr <= b);
  if (inHoliday) {
    const name = HOLIDAY_NAMES[dateStr] || HOLIDAY_NAMES[HOLIDAY_2026.holidays.find(([a, b]) => dateStr >= a && dateStr <= b)[0]] || "";
    return { type: "holiday", label: name || "法定假日" };
  }
  if (HOLIDAY_2026.workdays.includes(dateStr)) return { type: "makeup", label: "调休上班" };
  const d = new Date(dayStart(dateStr) + 4 * 3600000); // 正午取值，避开时区边界
  const w = d.getUTCDay();
  if (w === 0 || w === 6) return { type: "rest", label: "周末" };
  return { type: "work", label: "工作日" };
}

/* ---------------- 导出（全量备份 / CSV） ---------------- */
function csvEscape(v) {
  const s = v === null || v === undefined ? "" : String(v);
  return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}

function toLocalISO(ms) {
  if (ms === null || ms === undefined) return "";
  return new Date(ms + TZ).toISOString().slice(0, 19).replace("T", " ");
}

async function exportAll(env, format) {
  const res = await env.DB.prepare("SELECT * FROM sessions ORDER BY start_ms ASC").all();
  const rows = res.results || [];
  if (format === "csv") {
    const head = ["device", "app_key", "app_label", "start_local", "end_local", "duration_min", "source", "estimated"];
    const lines = [head.join(",")];
    for (const r of rows) {
      lines.push([
        csvEscape(r.device), csvEscape(r.app_key), csvEscape(r.app_label),
        csvEscape(toLocalISO(r.start_ms)), csvEscape(toLocalISO(r.end_ms)),
        csvEscape(r.duration_ms === null || r.duration_ms === undefined ? "" : (r.duration_ms / 60000).toFixed(2)),
        csvEscape(r.source), csvEscape(r.estimated),
      ].join(","));
    }
    // 加 BOM 让 Excel 正确识别 UTF-8
    return { body: "﻿" + lines.join("\r\n"), type: "text/csv; charset=utf-8", name: "app-time-export.csv" };
  }
  // 默认 JSON：与 time-pocket 备份格式兼容，可直接回灌 Android
  const apps = {};
  for (const r of rows) apps[r.app_key] = { pkg: r.app_key, label: r.app_label };
  const sessions = rows.map((r) => ({ pkg: r.app_key, start: r.start_ms, end: r.end_ms === null ? r.start_ms + 60000 : r.end_ms }));
  return {
    body: JSON.stringify({
      format: "time-pocket", version: 4, exportedAt: Date.now(),
      source: "app-time-cloud", count: sessions.length,
      apps: Object.values(apps), sessions,
    }),
    type: "application/json; charset=utf-8",
    name: "app-time-export.json",
  };
}

/* ---------------- 数据保留与清理 ---------------- */
async function cleanupOld(env, keepDays, dryRun) {
  let days = DEFAULT_RETENTION_DAYS;
  if (keepDays !== null && keepDays !== undefined && keepDays !== "") {
    const n = Number(keepDays);
    // keep_days=0 表示"只保留今天"，是一个合法的边界值，不能被当成缺省
    days = Number.isFinite(n) && n >= 0 ? Math.floor(n) : DEFAULT_RETENTION_DAYS;
  }
  const cutoff = Date.now() - days * 86400000;
  const before = await env.DB.prepare("SELECT COUNT(*) AS n FROM sessions WHERE start_ms < ?").bind(cutoff).first();
  const n = before && before.n ? before.n : 0;
  if (!dryRun && n > 0) {
    await env.DB.prepare("DELETE FROM sessions WHERE start_ms < ?").bind(cutoff).run();
  }
  return { status: dryRun ? "dry-run" : "ok", keep_days: days, cutoff, would_delete: n, deleted: dryRun ? 0 : n };
}

/* ---------------- 每日推送摘要 ---------------- */
// 支持 Bark / Server酱 / Telegram 三种渠道，按 PUSH_TYPE 环境变量选择
async function pushSummary(env, text, title) {
  const type = String((env && env.PUSH_TYPE) || "").toLowerCase();
  const hook = (env && env.PUSH_WEBHOOK) || "";
  if (!hook) return { status: "skipped", reason: "未配置 PUSH_WEBHOOK" };
  const t = title || "应用时间日报";
  let url = hook, payload = {};
  if (type === "telegram") {
    url = hook;
    payload = { chat_id: env.PUSH_CHAT_ID || "", text: t + "\n\n" + text };
  } else if (type === "serverchan" || type === "sct") {
    payload = { title: t, desp: text };
  } else {
    // 默认 Bark
    payload = { title: t, body: text };
  }
  const r = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  return { status: r.ok ? "ok" : "failed", http: r.status, type: type || "bark" };
}

/** 生成指定日期的文字摘要。 */
async function buildSummaryText(env, date, mode) {
  const rows = await querySessions(env, { date, device: "all", now: Date.now() });
  const s = summary(rows, date, "all", Date.now(), mode);
  const mins = Math.round(s.kpi.total_ms / 60000);
  const lines = [];
  lines.push(`${date} 共 ${Math.floor(mins / 60)} 小时 ${mins % 60} 分，打开 ${s.kpi.open_count} 次，${s.kpi.app_count} 个 App。`);
  const top = s.apps.slice(0, 5);
  if (top.length) {
    lines.push("用时最多：" + top.map((a) => `${a.label} ${Math.round(a.duration_ms / 60000)} 分`).join("、"));
  }
  // 与前一天对比
  const prevDate = localDateKey(dayStart(date) - 86400000);
  const prevRows = await querySessions(env, { date: prevDate, device: "all", now: Date.now() });
  const prev = summary(prevRows, prevDate, "all", Date.now(), mode);
  if (prev.kpi.total_ms > 0) {
    const delta = Math.round(((s.kpi.total_ms - prev.kpi.total_ms) / prev.kpi.total_ms) * 100);
    lines.push(`较前一天${delta >= 0 ? "增加" : "减少"} ${Math.abs(delta)}%。`);
  }
  return { text: lines.join("\n"), summary: s };
}

/* ---------------- 自动建表（一键部署后首次请求自动初始化） ---------------- */
// 说明：D1 的 DB.exec() 只能执行【单条】语句，多语句会被按换行切碎并报
// "incomplete input"。所以这里改成：先查表是否存在，不存在才用 prepare().run()
// 逐条建表；而且建表失败绝不能影响正常接口（表本来就可能是已建好的）。
const SCHEMA_STATEMENTS = ["CREATE TABLE IF NOT EXISTS sessions (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  device       TEXT    NOT NULL,\n  app_key      TEXT    NOT NULL,\n  app_label    TEXT    NOT NULL,\n  start_ms     INTEGER NOT NULL,\n  end_ms       INTEGER,\n  duration_ms  INTEGER,\n  source       TEXT    NOT NULL,\n  estimated    INTEGER NOT NULL DEFAULT 0,\n  created_at   INTEGER NOT NULL\n);", "CREATE UNIQUE INDEX IF NOT EXISTS idx_unique ON sessions(device, app_key, start_ms, source);", "CREATE INDEX IF NOT EXISTS idx_start ON sessions(start_ms);", "CREATE INDEX IF NOT EXISTS idx_device_open ON sessions(device, end_ms);", "CREATE TABLE IF NOT EXISTS meta (\n  k TEXT PRIMARY KEY,\n  v TEXT NOT NULL\n);"];
// 按数据库实例缓存，避免不同绑定之间互相干扰
const _schemaState = new WeakMap();

async function tableExists(env, name) {
  const r = await env.DB.prepare(
    "SELECT name FROM sqlite_master WHERE type='table' AND name=? LIMIT 1"
  ).bind(name).first();
  return Boolean(r && r.name);
}

async function ensureSchema(env) {
  if (!env || !env.DB) return;              // 未绑定 D1：交给后续调用报错，提示更明确
  if (_schemaState.has(env.DB)) return _schemaState.get(env.DB);
  const p = (async () => {
    // 1) 关键表在就直接跳过建表，绝大多数请求都会走这条路径
    try {
      const [s, m] = await Promise.all([tableExists(env, "sessions"), tableExists(env, "meta")]);
      if (s && m) return;
    } catch (e) { /* 查询失败则继续尝试建表 */ }
    // 2) 缺表才建：一条一条执行，避免多语句解析问题
    for (const stmt of SCHEMA_STATEMENTS) {
      try {
        await env.DB.prepare(stmt).run();
      } catch (e) { /* 单条失败不影响其它语句，也不阻断请求 */ }
    }
  })().catch(() => { _schemaState.delete(env.DB); }); // 失败可重试，但绝不向上抛
  _schemaState.set(env.DB, p);
  return p;
}

/* ---------------- 同步令牌与同步状态 ---------------- */// 若 Worker 里配置了环境变量 SYNC_TOKEN，则所有写入接口都必须带上 ?k=令牌 或 X-Sync-Token 头。
// 这样即使网址被他人知道，也无法写入或清空数据；手机上的自动化脚本也能安全地直接推送。
function tokenOk(env, url, request) {
  const expected = env && env.SYNC_TOKEN;
  if (!expected) return { ok: true, configured: false };
  const got = url.searchParams.get("k") || (request.headers.get("X-Sync-Token") || "");
  return { ok: got === expected, configured: true };
}

async function markSync(env, key, at) {
  try {
    await env.DB.prepare("INSERT OR REPLACE INTO meta(k, v) VALUES(?, ?)").bind(key, String(at)).run();
  } catch (e) {
    // meta 表可能尚未创建：不影响数据写入，仅少一个同步时间戳
  }
}

async function readSync(env) {
  const out = { android: null, ipad: null };
  try {
    const r = await env.DB.prepare("SELECT k, v FROM meta").all();
    for (const row of r.results || []) {
      if (row.k === "android" || row.k === "ipad") out[row.k] = Number(row.v) || null;
    }
  } catch (e) {
    // 同上，静默降级
  }
  return out;
}

/* ---------------- 路由 ---------------- */
export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const path = url.pathname;
    const cors = {
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Methods": "GET,POST,OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type, X-Sync-Token",
    };
    if (request.method === "OPTIONS") return new Response(null, { headers: cors });
    const json = (data, status = 200) =>
      new Response(JSON.stringify(data), { status, headers: Object.assign({}, cors, { "Content-Type": "application/json;charset=utf-8" }) });

    try {
      // 需要数据库的接口先自动建表（首次请求时执行一次，IF NOT EXISTS 幂等）
      if (path.startsWith("/api/") && path !== "/api/health" && path !== "/api/devices") {
        await ensureSchema(env);
      }
      if (path === "/" || path === "/index.html") {
        return new Response(HTML, { headers: { "Content-Type": "text/html;charset=utf-8" } });
      }

      // ---- PWA 资源：可离线打开、可"添加到主屏幕" ----
      if (path === "/manifest.webmanifest") {
        return new Response(MANIFEST, {
          headers: { "Content-Type": "application/manifest+json;charset=utf-8", "Cache-Control": "public, max-age=3600" },
        });
      }
      if (path === "/sw.js") {
        return new Response(SW, {
          headers: { "Content-Type": "application/javascript;charset=utf-8", "Cache-Control": "no-cache" },
        });
      }
      // Android 自动同步版 APK 下载
      if (path === "/app.apk" || path === "/时光口袋-自动同步版.apk") {
        if (!APK_B64) return new Response("apk not bundled", { status: 404 });
        const bin = Uint8Array.from(atob(APK_B64), (c) => c.charCodeAt(0));
        return new Response(bin, {
          headers: {
            "Content-Type": "application/vnd.android.package-archive",
            "Content-Disposition": 'attachment; filename="time-pocket-autosync.apk"',
            "Cache-Control": "public, max-age=86400",
          },
        });
      }

      if (path.startsWith("/icon-") || path === "/apple-touch-icon.png") {
        const key = path.slice(1);
        const data = ICONS[key];
        if (!data) return new Response("not found", { status: 404 });
        return new Response(data.bytes, {
          headers: { "Content-Type": "image/png", "Cache-Control": "public, max-age=86400" },
        });
      }

      if (path === "/api/health") return json({ ok: true, server_ms: Date.now() });
      if (path === "/api/devices") return json(DEVICES);

      if (path === "/api/ipad/event") {
        const tk = tokenOk(env, url, request);
        if (!tk.ok) return json({ error: "同步令牌无效" }, 401);
        let app, at;
        if (request.method === "GET") {
          app = url.searchParams.get("app");
          at = url.searchParams.get("at");
        } else {
          const b = await request.json();
          app = b.app; at = b.at;
        }
        const r = await addIpadEvent(env, app, at);
        await markSync(env, "ipad", Date.now());
        return json(r);
      }

      if (path === "/api/ipad/daily" && request.method === "POST") {
        const tk = tokenOk(env, url, request);
        if (!tk.ok) return json({ error: "同步令牌无效" }, 401);
        const r = await addIpadDaily(env, await request.text());
        await markSync(env, "ipad", Date.now());
        return json(r);
      }

      // 手机自动化（MacroDroid / HTTP Request Shortcuts / Termux 等）用它推送 time-pocket 备份：
      // POST 原始 JSON 正文即可，不需要表单上传，也不需要打开浏览器。
      if ((path === "/api/import/android" || path === "/api/ingest/android") && request.method === "POST") {
        const tk = tokenOk(env, url, request);
        if (!tk.ok) return json({ error: "同步令牌无效，请检查链接里的 ?k= 是否正确" }, 401);
        const text = await request.text();
        let data;
        try {
          data = JSON.parse(text);
        } catch (e) {
          return json({ error: "内容不是有效的 JSON，请确认推送的是 time-pocket 导出的 .json 备份" }, 400);
        }
        const r = await importTimepocket(env, data);
        await markSync(env, "android", Date.now());
        return json(r);
      }

      if (path === "/api/status") {
        const last = await readSync(env);
        let devices = [];
        let stats = { total: 0, first_ms: null, last_ms: null };
        try {
          const r = await env.DB.prepare(
            "SELECT device, COUNT(*) AS n, MAX(start_ms) AS latest FROM sessions GROUP BY device"
          ).all();
          devices = r.results || [];
          const g = await env.DB.prepare(
            "SELECT COUNT(*) AS n, MIN(start_ms) AS f, MAX(start_ms) AS l FROM sessions"
          ).first();
          if (g) stats = { total: g.n || 0, first_ms: g.f || null, last_ms: g.l || null };
        } catch (e) { /* 空库 */ }
        return json({
          server_ms: Date.now(),
          last_sync: last,
          devices,
          stats,
          token_required: Boolean(env && env.SYNC_TOKEN),
          push_configured: Boolean(env && env.PUSH_WEBHOOK),
          retention_days: env && env.RETENTION_DAYS ? Number(env.RETENTION_DAYS) : DEFAULT_RETENTION_DAYS,
        });
      }

      // 导出全量数据（JSON 可回灌 Android，CSV 用表格看）
      if (path === "/api/export") {
        const tk = tokenOk(env, url, request);
        if (!tk.ok) return json({ error: "同步令牌无效" }, 401);
        const format = (url.searchParams.get("format") || "json").toLowerCase();
        const out = await exportAll(env, format);
        return new Response(out.body, {
          headers: {
            "Content-Type": out.type,
            "Content-Disposition": `attachment; filename="${out.name}"`,
          },
        });
      }

      // 清理超出保留期的旧数据
      if (path === "/api/cleanup" && request.method === "POST") {
        const tk = tokenOk(env, url, request);
        if (!tk.ok) return json({ error: "同步令牌无效" }, 401);
        const keepDays = url.searchParams.get("keep_days");
        const dry = url.searchParams.get("dry") === "1";
        return json(await cleanupOld(env, keepDays, dry));
      }

      // 手动触发一次推送摘要（用于测试渠道是否通）
      if (path === "/api/push" && request.method === "POST") {
        const tk = tokenOk(env, url, request);
        if (!tk.ok) return json({ error: "同步令牌无效" }, 401);
        const date = url.searchParams.get("date") || localDateKey(Date.now() - 86400000);
        const built = await buildSummaryText(env, date, parseMode(url.searchParams.get("mode")));
        const r = await pushSummary(env, built.text, `${date} 使用时长小结`);
        return json(Object.assign({ date, text: built.text }, r));
      }

      // 节假日日历（供前端标注工作日 / 休息日）
      if (path === "/api/calendar") {
        const from = url.searchParams.get("from") || localDateKey(Date.now() - 30 * 86400000);
        const to = url.searchParams.get("to") || localDateKey(Date.now());
        const out = [];
        for (let t = dayStart(from); t <= dayStart(to); t += 86400000) {
          const d = localDateKey(t);
          out.push(Object.assign({ date: d }, dayType(d)));
        }
        return json(out);
      }

      if (path === "/api/reset" && request.method === "POST") {
        const tk = tokenOk(env, url, request);
        if (!tk.ok) return json({ error: "同步令牌无效" }, 401);
        await env.DB.prepare("DELETE FROM sessions").run();
        try { await env.DB.prepare("DELETE FROM meta").run(); } catch (e) {}
        return json({ status: "ok" });
      }

      const now = Date.now();
      const mode = parseMode(url.searchParams.get("mode"));
      const minMs = parseMinMs(url.searchParams.get("min_ms"));
      const q = (extra) => Object.assign({ mode, minMs, now }, extra);
      if (path === "/api/summary") {
        const date = url.searchParams.get("date") || localDateKey(now);
        const device = url.searchParams.get("device") || "all";
        return json(summary(await querySessions(env, q({ date, device })), date, device, now, mode));
      }
      if (path === "/api/trend") {
        const days = clampDays(url.searchParams.get("days"));
        const device = url.searchParams.get("device") || "all";
        return json(trend(await querySessions(env, q({ days, device })), days, now, mode));
      }
      if (path === "/api/heatmap") {
        const days = clampDays(url.searchParams.get("days"));
        const device = url.searchParams.get("device") || "all";
        return json(heatmap(await querySessions(env, q({ days, device })), now));
      }
      if (path === "/api/apps_range") {
        const days = clampDays(url.searchParams.get("days"));
        const device = url.searchParams.get("device") || "all";
        return json(appsRange(await querySessions(env, q({ days, device })), now, mode));
      }
      if (path === "/api/timeline") {
        const date = url.searchParams.get("date") || localDateKey(now);
        const device = url.searchParams.get("device") || "all";
        return json(timeline(await querySessions(env, q({ date, device })), date, now));
      }
      if (path === "/api/apps") {
        const res = await env.DB.prepare(
          "SELECT app_key,app_label,device,MAX(start_ms) AS last_ms FROM sessions GROUP BY app_key,app_label,device ORDER BY last_ms DESC"
        ).all();
        return json(res.results);
      }

      return json({ error: "not found" }, 404);
    } catch (e) {
      return json({ status: "error", message: String((e && e.message) || e) }, 400);
    }
  },

  /* 定时任务：每天早上推送昨日摘要，并顺带清理超期旧数据。
   * 在 Cloudflare 控制台 Worker → Settings → Triggers → Cron Triggers 添加：
   *   0 1 * * *   （UTC 1 点 = 北京时间 9 点）
   */
  async scheduled(event, env, ctx) {
    const now = Date.now();
    const date = localDateKey(now - 86400000); // 昨天
    const results = { date, push: null, cleanup: null };
    try {
      const built = await buildSummaryText(env, date, "sum");
      results.push = await pushSummary(env, built.text, `${date} 使用时长小结`);
    } catch (e) {
      results.push = { status: "error", message: String((e && e.message) || e) };
    }
    try {
      const keep = env.RETENTION_DAYS ? Number(env.RETENTION_DAYS) : DEFAULT_RETENTION_DAYS;
      results.cleanup = await cleanupOld(env, keep, false);
    } catch (e) {
      results.cleanup = { status: "error", message: String((e && e.message) || e) };
    }
    console.log("scheduled", JSON.stringify(results));
    return results;
  },
};

/* 供本地测试使用的导出（在 Worker 运行时会被忽略） */
export const __test = {
  tokenOk, readSync, markSync, summary, trend, heatmap, appsRange, timeline,
  effDur, estimateByGap, dayStart, localDateKey, localHour, addIpadEvent,
  importTimepocket, querySessions, parseIpadDaily, addIpadDaily, parseDurationMs,
  isDailyTotal, unionLength, sessionInterval, parseMode, parseMinMs, dayType,
  cleanupOld, exportAll, buildSummaryText, HOLIDAY_2026,
};

